FROM (VALUES
($j$chon-cay-tang-thay-co-20-11$j$, $j$phong-thuy$j$, $j$🍀 Tặng cây cho thầy cô ngày 20/11: chọn cây ý nghĩa, gọn gàng, dễ chăm trên bàn làm việc$j$, $j$Một chậu cây xanh nhỏ là món quà 20/11 trang nhã và bền lâu hơn bó hoa. Nên chọn cây chịu bóng, ít tưới, cỡ vừa bàn làm việc như lưỡi hổ, ngọc ngân, trầu bà, lan ý; kèm thiệp ghi cách chăm để thầy cô giữ cây được lâu.$j$, $j$[{"type":"p","text":"Hoa tươi ngày 20/11 đẹp nhưng chỉ vài ngày là tàn. Một chậu cây xanh nhỏ đặt trên bàn làm việc, bàn giáo viên thì ở lại lâu hơn nhiều — mỗi lần tưới cây, thầy cô lại nhớ tới học trò. Để món quà không thành gánh nặng, cây cần **đẹp, gọn và thật dễ chăm**."},{"type":"h2","text":"🎁 Vì sao cây xanh là món quà hợp 20/11?"},{"type":"list","items":["**Bền lâu**: cây chăm đúng có thể sống nhiều năm.","**Ý nghĩa**: cây lớn lên từng ngày, giống công \"trồng người\" của thầy cô.","**Hợp nhiều ngân sách**: từ chậu nhỏ để bàn tới chậu lớn cả lớp góp tặng.","**Thiết thực**: tạo góc xanh dễ chịu ở phòng giáo viên, phòng làm việc."],"ordered":false},{"type":"h2","text":"🛒 Những cây hợp làm quà 20/11"},{"type":"table","rows":[["Cây","Ý nghĩa thường gửi gắm","Vì sao dễ chăm"],["Lưỡi hổ","Mạnh mẽ, bền bỉ","Chịu bóng, 1–2 tuần tưới một lần"],["Ngọc ngân","Thanh khiết, may mắn","Chịu bóng, có thể trồng thủy sinh"],["Trầu bà đế vương","Vững vàng, phát triển","Lá dày bền, chịu máy lạnh khá"],["Lan ý","Bình yên, thanh tao","Hoa trắng; lá rũ là báo khát nước"],["Kim ngân, phú quý","Sung túc, tốt lành","Chịu bóng, lá màu tươi"],["Ngọc bích","Sung túc, bền lâu","Ít tưới — hợp bàn gần cửa sổ sáng"]]},{"type":"p","text":"Ý nghĩa trên là cách hiểu dân gian quen thuộc, giúp tấm thiệp thêm lời chúc. Điều quan trọng nhất vẫn là cây khỏe và hợp chỗ đặt."},{"type":"h2","text":"📍 Thầy cô sẽ đặt cây ở đâu?"},{"type":"table","rows":[["Chỗ đặt","Nên chọn"],["Bàn giáo viên trong lớp, gần cửa sổ","Ngọc bích, lan ý, phú quý"],["Phòng giáo viên có máy lạnh, ít sáng","Lưỡi hổ, ngọc ngân, trầu bà đế vương"],["Nhà riêng, có ban công","Cây hoa: mai địa thảo, hoa hồng chậu (nếu thầy cô thích chăm)"],["Cả lớp góp tặng trường","Cây đứng chậu lớn cho sảnh, phòng hội đồng"]]},{"type":"h2","text":"🪴 Chọn chậu và gói quà"},{"type":"list","items":["Chậu nhỏ đường kính 12–18cm cho bàn làm việc, **có lỗ thoát nước và đĩa lót** để khỏi ướt giấy tờ.","Chậu sứ trắng, chậu gốm màu trơn nhìn trang nhã; tránh chậu quá nặng.","Phủ mặt chậu bằng sỏi trắng để sạch sẽ, đất không vương ra bàn.","Gói bằng giấy kraft, nơ vải; không bọc kín ni lông nhiều ngày vì cây bí hơi."],"ordered":false},{"type":"h2","text":"📝 Viết thiệp: lời chúc + cách chăm"},{"type":"p","text":"Ngoài lời tri ân, thêm 3 dòng hướng dẫn giúp thầy cô giữ cây lâu: **tên cây, đặt ở đâu, bao lâu tưới một lần**. Ví dụ: \"Lưỡi hổ — đặt nơi sáng nhẹ — tưới nửa ly nước khi đất khô hẳn, khoảng 10–14 ngày một lần.\""},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Tặng cây trước 1–2 ngày thay vì đúng sáng 20/11: thầy cô kịp mang về chỗ đặt, không phải để cây trong túi giấy suốt buổi lễ."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chọn cây ưa nắng** như sen đá, xương rồng cho phòng máy lạnh thiếu sáng: vài tuần là vống, thối.","**Chậu không lỗ thoát nước** đi kèm bộ quà: thầy cô tưới theo thói quen, cây úng rễ.","**Cây quá to** cho bàn làm việc, che màn hình, vướng giấy tờ.","**Cây có gai, nhựa độc** cho cô giáo mầm non, tiểu học — trẻ nhỏ hay sờ nghịch."],"ordered":false},{"type":"h2","text":"🌱 Gợi ý theo cấp học"},{"type":"table","rows":[["Người nhận","Gợi ý","Lý do"],["Cô giáo mầm non, tiểu học","Lan chi, dương xỉ, ngọc ngân thủy sinh","An toàn hơn khi trẻ nhỏ hay sờ nghịch"],["Giáo viên THCS, THPT","Lưỡi hổ, trầu bà đế vương, phú quý","Bền, chịu phòng máy lạnh"],["Giảng viên đại học, thầy hướng dẫn","Ngân hậu, bạch mã chậu vừa","Dáng sang, hợp phòng làm việc riêng"],["Thầy cô đã nghỉ hưu","Tùng thơm, ngọc bích, vạn niên thanh","Có thời gian chăm, ý nghĩa bền lâu"]]},{"type":"h2","text":"🤝 Cả lớp cùng tặng một chậu"},{"type":"p","text":"Thay vì mỗi bạn một bó hoa nhỏ, cả lớp có thể góp tiền tặng một chậu cây lớn hơn cho phòng hội đồng, thư viện hay góc lớp. Một tấm bảng nhỏ ghi \"Lớp … tặng thầy cô nhân ngày 20/11\" cắm vào chậu sẽ thành kỷ niệm nhiều năm. Nên cử 2–3 bạn đi chọn cây, hỏi trước thầy cô chỗ đặt để chọn loại cây hợp ánh sáng. Sau đó, lớp có thể nhận luôn việc tưới cây hằng tuần — vừa là món quà, vừa là một hoạt động gắn bó."},{"type":"p","text":"Nếu tặng nhiều chậu cho trường, đặt trước với nhà vườn để chọn cây cùng cỡ, cùng kiểu chậu cho đồng bộ."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Học sinh nên tặng cây giá bao nhiêu?"},{"type":"p","text":"Không cần đắt. Một chậu cây nhỏ khỏe, chậu sạch đẹp và tấm thiệp viết tay đã đủ ý nghĩa. Cả lớp có thể góp chung một chậu lớn hơn."},{"type":"h3","text":"Tặng cây cho thầy giáo nam có hợp không?"},{"type":"p","text":"Rất hợp. Lưỡi hổ, trầu bà đế vương, ngân hậu có dáng khỏe, màu lá trầm, đặt bàn làm việc nhìn gọn gàng."},{"type":"h3","text":"Cây đặt phòng máy lạnh có sống được không?"},{"type":"p","text":"Được nếu chọn cây chịu bóng và đặt xa cửa gió. Xem [chăm cây trong phòng máy lạnh](/goc-cham-cay/cham-cay-trong-phong-may-lanh)."},{"type":"products","title":"Dùng trong bài này","slugs":["luoi-ho","ngoc-ngan","trau-ba-de-vuong-xanh","lan-y","phu-quy","ngoc-bich"]},{"type":"p","text":"Xem thêm [chọn cây làm quà khai trương, tân gia, sinh nhật](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia) và [cây để bàn làm việc dễ chăm](/goc-cham-cay/cay-de-ban-lam-viec-de-cham)."}]$j$, 5, ARRAY[]::text[], ARRAY[$j$quà tặng$j$,$j$20/11$j$,$j$cây để bàn$j$]::text[], $j$Gợi ý cây tặng thầy cô ngày 20/11: cây ý nghĩa, chịu bóng, dễ chăm trên bàn làm việc, cách chọn chậu và viết thiệp hướng dẫn chăm cây.$j$, $j$2026-11-18 07:30:00+07$j$),
($j$chuan-bi-vuon-chuyen-mua-mua-sang-mua-kho$j$, $j$theo-mua$j$, $j$🌦️ Cuối mùa mưa, đầu mùa khô: 7 việc chuẩn bị cho vườn cây và chậu cảnh ở miền Tây$j$, $j$Giai đoạn chuyển từ mùa mưa sang mùa khô là lúc dọn vườn, tỉa cành, thay đất, kiểm tra sâu bệnh và chuẩn bị nước tưới. Làm sớm giúp cây hồi sức sau mưa dầm, chuẩn bị ra hoa Tết và chịu được nắng nóng, gió chướng, nhiễm mặn sắp tới.$j$, $j$[{"type":"p","text":"Ở miền Tây, mùa mưa thường kéo dài tới khoảng tháng 11, sau đó trời chuyển dần sang mùa khô với nắng nhiều, gió chướng và ở vùng ven biển là nguy cơ nhiễm mặn. Đây là **thời điểm vàng để \"dọn nhà\" cho vườn cây**: cây vừa qua mấy tháng ẩm ướt, lại sắp bước vào mùa ra hoa Tết."},{"type":"h2","text":"✅ 7 việc nên làm"},{"type":"list","items":["**Dọn lá mục, cành khô**: nơi trú ẩn của ốc sên, nấm bệnh sau mùa mưa.","**Tỉa cành tạo tán thoáng**: cắt cành sâu bệnh, cành mọc vống trong mùa mưa.","**Kiểm tra rễ chậu bị úng**: chậu nào đất có mùi chua, cây vàng lá thì nhấc ra xem rễ.","**Thay đất, xới đất mặt**: đất chậu sau mùa mưa thường nén chặt, mất dinh dưỡng.","**Bón phân hữu cơ hồi sức** cho cây sau mưa dầm.","**Chuẩn bị nước tưới**: vệ sinh lu, bồn; vùng ven biển chuẩn bị trữ nước ngọt.","**Chuẩn bị vật liệu phủ gốc**: rơm, xơ dừa, lá khô để giữ ẩm mùa nắng."],"ordered":true},{"type":"h2","text":"🔁 Đổi cách chăm từ mùa mưa sang mùa khô"},{"type":"table","rows":[["Việc","Mùa mưa","Mùa khô"],["Tưới","Ít, nhiều ngày không cần","Thường xuyên hơn, sáng sớm hoặc chiều mát"],["Sâu bệnh chính","Nấm, thối rễ, ốc sên","Nhện đỏ, rệp, bọ trĩ, bọ phấn"],["Chỗ đặt chậu","Có mái che mưa, kê cao","Tránh nắng chiều gắt cho cây lá mỏng"],["Phân bón","Hạn chế khi mưa dầm","Bón đều, liều vừa, tưới đủ nước"]]},{"type":"h2","text":"🕷️ Đề phòng sâu hại mùa khô"},{"type":"p","text":"Không khí khô, nắng nóng là điều kiện thuận lợi cho [nhện đỏ](/benh-cay/nhen-do), [bọ trĩ](/benh-cay/bo-tri) và [rệp muội](/benh-cay/rep-muoi). Mỗi tuần nên lật mặt dưới lá kiểm tra, phun nước mặt dưới lá vào sáng sớm cho cây kiểng lá ngoài ban công. Xem [nhện đỏ mùa khô trên cây cảnh](/goc-cham-cay/nhen-do-mua-kho-cay-canh)."},{"type":"h2","text":"🧂 Vùng có nguy cơ nhiễm mặn"},{"type":"list","items":["Theo dõi thông báo độ mặn của địa phương vào mùa khô.","Trữ nước ngọt trước khi mặn xâm nhập sâu.","Kiểm tra nước giếng, nước sông trước khi tưới.","Xem chi tiết: [phòng mặn cho cây sân vườn](/goc-cham-cay/phong-man-cho-cay-san-vuon)."],"ordered":false},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Lập một tờ lịch nhỏ dán gần chỗ để dụng cụ làm vườn: tuần này làm gì, tuần sau làm gì. Việc lớn chia nhỏ ra thì làm đều và ít bỏ sót hơn."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Giữ thói quen tưới ít của mùa mưa** khi nắng đã gắt: cây héo, rụng nụ.","**Thay chậu, tỉa mạnh ngay trước Tết vài ngày**: cây không kịp hồi.","**Bỏ qua chậu bị úng từ mùa mưa**: rễ thối âm thầm, cây chết khi vào nắng."],"ordered":false},{"type":"h2","text":"🗓️ Lịch gợi ý 4 tuần chuyển mùa"},{"type":"table","rows":[["Tuần","Việc chính"],["Tuần 1","Dọn lá mục, cành khô; kiểm tra chậu úng, nhấc rễ những chậu nghi ngờ"],["Tuần 2","Tỉa cành tạo tán; thay đất, xới đất mặt; bón phân hữu cơ hồi sức"],["Tuần 3","Vệ sinh lu, bồn chứa; trữ nước; kiểm tra vòi, ống tưới"],["Tuần 4","Phủ gốc; kiểm tra sâu hại mùa khô; chuẩn bị lịch chăm cây Tết"]]},{"type":"h2","text":"🧹 Vệ sinh dụng cụ làm vườn"},{"type":"p","text":"Kéo cắt cành, xẻng, bình tưới sau mùa mưa thường dính bùn, rỉ sét và có thể mang mầm bệnh từ cây này sang cây khác. Rửa sạch, lau khô, lau lưỡi kéo bằng cồn và tra một chút dầu. Bình phun đã dùng thuốc phải rửa kỹ và để riêng. Dụng cụ sạch giúp vết cắt mau lành, hạn chế lây bệnh khi tỉa cành hàng loạt vào cuối năm."},{"type":"h2","text":"🌱 Gieo gì cho mùa khô?"},{"type":"list","items":["Rau ăn lá ưa mát như xà lách, cải: trồng được cuối năm khi trời bớt oi.","Rau chịu nắng như rau dền, mồng tơi, rau muống: trồng quanh mùa khô nếu đủ nước.","Cây ăn trái, cà, ớt: trồng đầu mùa khô, tưới đều."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Khi nào bắt đầu mùa khô ở miền Tây?"},{"type":"p","text":"Thường khoảng tháng 11–12 và kéo dài tới khoảng tháng 4–5, tùy năm. Theo dõi thời tiết thực tế hơn là lịch cố định."},{"type":"h3","text":"Có nên thay chậu vào cuối năm không?"},{"type":"p","text":"Được, nếu làm sớm (trước Tết ít nhất 1 tháng) cho cây kịp hồi phục. Xem [thay chậu cây cảnh đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach)."},{"type":"h3","text":"Phủ gốc bằng gì tốt?"},{"type":"p","text":"Rơm, xơ dừa, lá khô, vỏ thông đều được; phủ cách gốc vài cm để cổ rễ thông thoáng."},{"type":"p","text":"Xem thêm [chăm cây mùa khô nắng nóng](/goc-cham-cay/cham-cay-mua-kho-nang-nong) và [lịch chăm cây 12 tháng miền Tây](/goc-cham-cay/lich-cham-cay-12-thang-mien-tay)."}]$j$, 4, ARRAY[$j$nhen-do$j$,$j$thoi-re$j$]::text[], ARRAY[$j$mùa khô$j$,$j$chăm vườn$j$,$j$miền Tây$j$]::text[], $j$Chuẩn bị vườn cây, chậu cảnh khi chuyển từ mùa mưa sang mùa khô ở miền Tây: tỉa cành, thay đất, phòng sâu bệnh, trữ nước, phủ gốc, phòng mặn.$j$, $j$2026-11-19 07:30:00+07$j$),
($j$cay-chay-la-trang-sau-khi-dem-ra-nang$j$, $j$bat-benh$j$, $j$🐛 Cây cháy lá trắng, lá bạc màu sau khi đem ra nắng: vì sao và cách cứu cây bị sốc nắng$j$, $j$Cây quen bóng bị đưa thẳng ra nắng sẽ cháy lá: mảng trắng bạc hoặc nâu khô ở phần lá hứng nắng, thường xuất hiện sau 1–2 ngày. Lá cháy không xanh lại, nhưng cây hồi phục nếu đưa vào bóng râm, tưới đều và cho làm quen nắng dần trong 1–2 tuần.$j$, $j$[{"type":"p","text":"Thấy cây trong nhà lá nhạt màu, nhiều người mang cây ra sân \"phơi nắng cho khỏe\". Một hai hôm sau, lá xuất hiện những mảng trắng bạc như bị tẩy, rồi khô nâu giòn. Đây là **cháy lá do nắng** — cây không bị bệnh, mà bị sốc ánh sáng."},{"type":"h2","text":"🔍 Nhận biết cháy lá do nắng"},{"type":"list","items":["Mảng **trắng bạc, vàng nhạt** rồi chuyển nâu khô, ở phần lá hướng về phía nắng.","Xuất hiện nhanh, thường trong 1–3 ngày sau khi đổi chỗ.","Lá phía trong tán, lá bị che khuất vẫn xanh bình thường.","Không có viền vàng lan rộng, không có đốm nhỏ lan dần như bệnh nấm."],"ordered":false},{"type":"p","text":"Xem thêm trong thư viện: [cháy lá do nắng](/benh-cay/chay-la-do-nang)."},{"type":"h2","text":"🔎 Vì sao cây quen bóng lại cháy?"},{"type":"p","text":"Lá mọc trong bóng râm mỏng hơn, có lớp bảo vệ yếu hơn lá mọc ngoài nắng. Khi gặp nắng trực tiếp đột ngột, lá nhận nhiều ánh sáng và nhiệt hơn khả năng chịu đựng, mô lá bị tổn thương. Nắng trưa và nắng chiều ở miền Tây đặc biệt gắt, kết hợp với đất khô thì lá cháy càng nhanh."},{"type":"h2","text":"🧭 Phân biệt với các nguyên nhân khác"},{"type":"table","rows":[["Dấu hiệu","Cháy nắng","Bệnh nấm, vi khuẩn","Cháy do phân"],["Vị trí","Phần lá hứng nắng","Rải rác, lan dần","Mép, đầu lá nhiều lá"],["Tốc độ","Nhanh sau khi đổi chỗ","Lan dần nhiều ngày","Sau khi bón đậm"],["Hình dạng","Mảng lớn trắng bạc, nâu","Đốm tròn có viền, quầng vàng","Cháy viền nâu đều"]]},{"type":"p","text":"Nếu đốm lan dần, có viền, xem [đốm lá do nấm](/benh-cay/dom-la-nam) hoặc [cháy lá vi khuẩn](/benh-cay/chay-la-vi-khuan); nếu vừa bón phân đậm, xem [cháy rễ do bón phân](/benh-cay/chay-re-do-phan)."},{"type":"h2","text":"🛠️ Cứu cây bị cháy nắng"},{"type":"list","items":["Đưa cây vào **chỗ sáng nhưng không nắng trực tiếp** ngay.","Kiểm tra đất; tưới đẫm nếu đất khô (không tưới khi đất còn ướt).","Không cắt lá vội: lá cháy một phần vẫn quang hợp ở phần còn xanh.","Không bón phân trong 2–3 tuần — rễ và lá đang yếu.","Cắt lá cháy hoàn toàn khi cây đã ra lá mới."],"ordered":true},{"type":"h2","text":"☀️ Cho cây làm quen nắng đúng cách"},{"type":"table","rows":[["Thời gian","Cách làm"],["Ngày 1–3","Đặt chỗ sáng có bóng râm, chỉ nhận nắng sớm trước 8 giờ"],["Ngày 4–7","Tăng lên nắng buổi sáng tới khoảng 9–10 giờ"],["Tuần 2","Nắng sáng tới gần trưa, che nắng trưa và chiều"],["Sau 2 tuần","Cây ưa nắng có thể ra hẳn; cây chịu bóng chỉ nên giữ nắng sáng"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Không phải cây nào cũng cần \"tập nắng\". Cây chịu bóng như ngọc ngân, ngân hậu, đuôi công, lan ý chỉ hợp ánh sáng tán xạ — đem ra nắng gắt thì dù tập dần vẫn cháy."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đem cây mới mua từ nhà vườn có lưới che ra thẳng nắng gắt**.","**Tưới lên lá giữa trưa nắng** với hy vọng làm mát.","**Bón phân \"cho cây khỏe lại\"** ngay sau khi cháy.","**Để chậu nhựa đen ngoài nắng chiều**: rễ cũng bị nóng."],"ordered":false},{"type":"h2","text":"🔥 Kính, tường và gạch cũng làm cây cháy"},{"type":"p","text":"Không chỉ nắng trực tiếp: cây đặt sát cửa kính hướng Tây có thể bị cháy lá do nắng chiều chiếu qua kính, không khí sát kính rất nóng. Tường sơn trắng, tường kính, nền gạch sáng màu trên sân thượng cũng phản chiếu và hắt nhiệt lên cây. Nếu cây ở những chỗ này, lùi chậu cách kính một khoảng, dùng rèm mỏng hoặc kê chậu lên kệ gỗ thay vì đặt thẳng trên nền gạch nóng."},{"type":"h2","text":"🪴 Cây nào cần nắng, cây nào sợ nắng?"},{"type":"table","rows":[["Nhóm","Ví dụ","Nắng phù hợp"],["Ưa nắng","Hoa giấy, mai địa thảo, sen đá, rau ăn trái","Nắng trực tiếp nhiều giờ (sau khi đã quen)"],["Chịu nắng nhẹ","Lưỡi hổ, ngọc bích, trầu bà","Nắng sáng, tránh trưa chiều"],["Sợ nắng","Đuôi công, ngọc ngân, ngân hậu, dương xỉ, lan ý","Sáng tán xạ, không nắng trực tiếp"]]},{"type":"p","text":"Khi không rõ cây thuộc nhóm nào, hãy coi như cây sợ nắng và chỉ cho nhận nắng sớm, quan sát lá trong 1 tuần."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Lá bị cháy nắng có xanh lại không?"},{"type":"p","text":"Không. Phần mô đã cháy giữ nguyên. Cây sẽ ra lá mới thay thế khi được đặt đúng chỗ."},{"type":"h3","text":"Sen đá, xương rồng có bị cháy nắng không?"},{"type":"p","text":"Có, nếu đang quen bóng mà đưa ra nắng gắt đột ngột. Cần tập nắng từ từ như cây khác."},{"type":"h3","text":"Có cần che lưới cho cây ngoài ban công?"},{"type":"p","text":"Ban công hướng Tây nắng gắt nên che lưới cắt nắng cho cây lá mỏng. Xem [cây cho ban công nắng gắt](/goc-cham-cay/cay-ban-cong-nang-gat)."},{"type":"p","text":"Xem thêm [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha) và [chăm cây mới mua về](/goc-cham-cay/cham-soc-cay-moi-mua-ve)."}]$j$, 4, ARRAY[$j$chay-la-do-nang$j$]::text[], ARRAY[$j$cháy lá$j$,$j$ánh nắng$j$,$j$cây trong nhà$j$]::text[], $j$Cây bị cháy lá trắng, bạc màu sau khi đem ra nắng: nhận biết cháy nắng, phân biệt với bệnh, cách cứu và cho cây làm quen ánh nắng từ từ.$j$, $j$2026-11-20 07:30:00+07$j$),
($j$trong-xa-lach-thung-xop$j$, $j$rau-sach$j$, $j$🥬 Trồng xà lách trong thùng xốp mùa khô: gieo, che nắng, tưới để rau giòn, không đắng$j$, $j$Xà lách trồng thùng xốp rất hợp mùa khô cuối năm ở miền Tây. Gieo hạt trên khay, cấy sang thùng khi có 3–4 lá, đặt nơi nắng sáng có che trưa, tưới đều mỗi ngày; khoảng 30–45 ngày là thu hoạch được rau giòn, ít đắng.$j$, $j$[{"type":"p","text":"Xà lách là loại rau ăn sống quen thuộc trong bữa cơm, cuốn bánh tráng. Rau tự trồng hái xong ăn ngay giòn ngọt hơn hẳn. Xà lách ưa mát nên **mùa khô cuối năm, khi trời bớt oi**, là lúc trồng dễ nhất ở miền Tây."},{"type":"h2","text":"🌱 Chọn giống xà lách"},{"type":"table","rows":[["Giống","Đặc điểm","Ghi chú"],["Xà lách xoăn (lá xanh, lá tím)","Lá rời, mềm, dễ trồng","Hái lá dần được"],["Xà lách búp (lô lô, búp mỡ)","Cuộn búp, lá dày","Cần mát hơn, chậm hơn"],["Xà lách romaine","Lá dài, giòn","Chịu nóng khá hơn"],["Xà lách địa phương lá nhỏ","Chịu nóng tốt","Hợp trồng mùa nóng"]]},{"type":"h2","text":"🪴 Gieo hạt và cấy cây con"},{"type":"list","items":["Gieo hạt lên khay ươm hoặc thùng nhỏ chứa giá thể mịn, rải thưa, phủ lớp đất rất mỏng.","Phun sương giữ ẩm, đặt chỗ mát; hạt nảy mầm sau vài ngày.","Khi cây có 3–4 lá thật, cấy sang thùng xốp vào chiều mát, cây cách cây khoảng 15–20cm.","Che nắng 2–3 ngày đầu sau khi cấy cho cây bén rễ."],"ordered":true},{"type":"h2","text":"🌤️ Đất, nắng và che mát"},{"type":"list","items":["Thùng sâu 15–20cm, có lỗ thoát nước; đất tơi trộn phân trùn quế hoặc phân hữu cơ hoai.","Cần nắng sáng 4–6 giờ; **che lưới vào buổi trưa** những ngày nắng gắt.","Nắng nóng kéo dài làm xà lách nhanh trổ ngồng, lá đắng."],"ordered":false},{"type":"h2","text":"💧 Tưới và bón"},{"type":"list","items":["Tưới đều mỗi ngày vào sáng sớm, giữ đất ẩm, không để khô rồi tưới bù.","Tưới gốc, hạn chế tưới đẫm lên lá chiều tối để tránh thối lá.","7–10 ngày một lần tưới nước phân hữu cơ hoặc phân trùn quế pha loãng."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch"},{"type":"p","text":"Xà lách lá rời có thể **hái lá ngoài dần** từ khoảng 3–4 tuần sau cấy, chừa lõi để cây ra lá mới. Muốn thu cả cây, cắt sát gốc khi cây đủ lớn, trước khi cây bắt đầu vươn ngồng. Hái vào sáng sớm, rau giòn và tươi lâu hơn."},{"type":"h2","text":"🐛 Sâu bệnh thường gặp"},{"type":"table","rows":[["Vấn đề","Xử lý"],["Sâu ăn lá, sâu xanh","Bắt tay, kiểm tra mặt dưới lá"],["Ốc sên, sên trần","Bắt ban đêm, dọn chỗ ẩm — xem [ốc sên ăn lá](/goc-cham-cay/oc-sen-an-la-ban-cong)"],["Rệp ở lõi","Xịt nước, ngắt lá bị nặng"],["Thối gốc mùa mưa","Thùng thoát nước tốt, tưới gốc, không trồng dày"]]},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Xà lách là rau ăn sống: không phun thuốc hóa học. Ưu tiên bắt tay, che lưới, rửa rau kỹ dưới vòi nước trước khi ăn."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Trồng giữa mùa nóng không che**: rau trổ ngồng, đắng.","**Gieo dày, không tỉa**: cây nhỏ, lá mỏng.","**Tưới thất thường**: lá dai, đắng, mép lá cháy.","**Để quá lứa**: cây vươn ngồng, lá cứng."],"ordered":false},{"type":"h2","text":"⏱️ Gieo gối để có rau ăn liên tục"},{"type":"p","text":"Xà lách thu hoạch nhanh nhưng cũng nhanh già. Thay vì gieo một lần cả thùng, hãy gieo một khay nhỏ mỗi 1–2 tuần. Khi thùng đầu tiên thu hoạch xong, khay sau đã có cây con sẵn để cấy. Cách này giúp gia đình có rau tươi đều đặn mà không bị dư thừa rau già cùng lúc."},{"type":"h2","text":"🧺 Rửa và bảo quản xà lách"},{"type":"list","items":["Hái vào sáng sớm, nhúng nhanh vào nước mát cho lá tươi giòn.","Tách từng lá, rửa dưới vòi nước chảy, chú ý phần nách lá gần gốc.","Để ráo hoặc dùng rổ quay ráo nước.","Cuộn trong khăn giấy, cho vào hộp kín, cất ngăn mát — giữ được vài ngày."],"ordered":true},{"type":"h2","text":"🌿 Giá thể nhẹ cho sân thượng"},{"type":"p","text":"Sân thượng chịu tải hạn chế, nhiều thùng đất nặng tích lại khá nặng. Có thể dùng hỗn hợp nhẹ hơn: xơ dừa đã xả chát, trấu hun và phân trùn quế, trộn với một phần đất. Giá thể nhẹ còn thoát nước tốt, rễ xà lách phát triển mạnh; chỉ cần tưới đều và bổ sung phân hữu cơ thường xuyên hơn."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Vì sao xà lách bị đắng?"},{"type":"p","text":"Thường do nắng nóng, thiếu nước hoặc cây đã già, bắt đầu trổ ngồng. Thu hoạch đúng lúc và che nắng trưa giúp rau ít đắng."},{"type":"h3","text":"Trồng xà lách mùa mưa được không?"},{"type":"p","text":"Được nếu có mái che mưa, thùng thoát nước tốt và trồng thưa. Mưa dầm dễ làm thối lá."},{"type":"h3","text":"Một thùng xốp trồng mấy cây?"},{"type":"p","text":"Thùng thông dụng khoảng 60×40cm trồng được khoảng 6–8 cây xà lách lá rời."},{"type":"p","text":"Trồng thêm: [rau cải thùng xốp](/goc-cham-cay/trong-rau-cai-thung-xop), [rau dền tại nhà](/goc-cham-cay/trong-rau-den-tai-nha)."}]$j$, 4, ARRAY[]::text[], ARRAY[$j$xà lách$j$,$j$rau sạch$j$,$j$thùng xốp$j$]::text[], $j$Cách trồng xà lách trong thùng xốp tại nhà: chọn giống, gieo hạt, cấy cây con, che nắng, tưới bón và thu hoạch để rau giòn, không đắng.$j$, $j$2026-11-21 07:30:00+07$j$),
($j$kiem-tra-cay-khi-nhan-hang-giao-xa$j$, $j$cam-nang$j$, $j$📗 Mua cây online, nhận cây giao xa: kiểm tra gì khi mở thùng và chăm thế nào trong tuần đầu$j$, $j$Cây giao xa thường bị sốc do nhiều giờ trong thùng tối. Khi nhận, kiểm tra bầu đất, thân, lá, sâu bệnh và chụp ảnh ngay; đặt cây nơi sáng nhẹ, không nắng gắt, tưới vừa phải, chưa thay chậu và chưa bón phân trong 1–2 tuần đầu.$j$, $j$[{"type":"p","text":"Mua cây qua mạng, cây được giao từ vườn tới nhà sau vài giờ tới vài ngày trong thùng carton. Phần lớn cây vẫn khỏe, nhưng **tuần đầu tiên quyết định** cây có bén chỗ mới hay rụng lá liên tục. Dưới đây là những việc nên làm ngay khi nhận cây."},{"type":"h2","text":"📦 Khi mở thùng: 5 việc làm ngay"},{"type":"list","items":["**Quay video hoặc chụp ảnh lúc mở thùng** — có bằng chứng nếu cần đổi trả.","Gỡ băng keo, mút xốp nhẹ tay, nhấc cây ra bằng chậu, không kéo thân.","Kiểm tra bầu đất: còn nguyên khối hay bị vỡ, rễ có bị lộ, đứt.","Xem thân, cành có gãy dập; lá có rách nhiều, vàng úa bất thường.","Lật mặt dưới lá, nách lá: có rệp sáp, nhện, ốc sên đi theo không."],"ordered":true},{"type":"h2","text":"🔍 Bình thường hay có vấn đề?"},{"type":"table","rows":[["Tình trạng","Có thường gặp không?","Nên làm gì"],["Vài lá gốc vàng, rụng","Có — do thiếu sáng khi vận chuyển","Cắt bỏ, theo dõi"],["Lá hơi rũ, đất khô","Có","Tưới vừa phải, đặt chỗ mát"],["Thân gãy, bầu vỡ nặng","Không","Chụp ảnh, liên hệ shop ngay"],["Có sâu, rệp, ốc","Đôi khi","Cách ly, xử lý trước khi đặt cạnh cây khác"],["Thân mềm nhũn, mùi hôi","Không","Báo shop, kiểm tra rễ"]]},{"type":"h2","text":"🪴 Chăm cây trong 2 tuần đầu"},{"type":"table","rows":[["Thời gian","Việc cần làm"],["Ngày 1","Đặt nơi sáng tán xạ, thoáng; tưới nếu đất khô"],["Ngày 2–7","Không dời chỗ liên tục; tưới khi mặt đất khô 2–3cm"],["Tuần 2","Cây quen dần; cây ưa nắng có thể tập nắng sáng từ từ"],["Sau 2–3 tuần","Thay chậu đẹp, bón phân nếu cần"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Đừng thay chậu và bón phân ngay ngày nhận: cây đang mệt sau vận chuyển, thêm một cú sốc nữa dễ rụng lá hàng loạt."},{"type":"h2","text":"🧳 Cách ly cây mới"},{"type":"p","text":"Để cây mới riêng một chỗ khoảng 1 tuần, cách xa các chậu cũ. Đây là cách đơn giản nhất để không mang rệp sáp, nhện, bọ phấn từ nơi khác vào vườn nhà. Trong thời gian này, kiểm tra mặt dưới lá vài lần."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đem cây ra nắng gắt ngay** cho \"tỉnh lại\": cây quen tối trong thùng sẽ cháy lá.","**Tưới đẫm liền dù đất còn ẩm**: cây yếu, dễ úng.","**Vứt thùng, bỏ phiếu giao hàng trước khi kiểm tra**.","**Thấy rụng vài lá là hoảng, dời chỗ liên tục**."],"ordered":false},{"type":"h2","text":"🌿 Lưu ý theo loại cây"},{"type":"table","rows":[["Loại cây","Kiểm tra thêm","Chăm tuần đầu"],["Cây kiểng lá","Lá rách, gãy cuống","Sáng tán xạ, tưới vừa"],["Cây mọng nước, sen đá","Lá rụng, thân mềm","Chưa tưới 2–3 ngày, để khô thoáng"],["Cây đang có hoa","Hoa, nụ dập, rụng","Chỗ sáng thoáng, tưới gốc"],["Cây lớn, cây công trình","Bầu rễ, thân trầy","Tưới đẫm, che nắng vài ngày"],["Cây thủy sinh","Rễ khô, thối","Thả vào nước sạch ngay"]]},{"type":"h2","text":"📸 Lưu giữ thông tin cây"},{"type":"p","text":"Chụp ảnh nhãn cây, ghi tên cây, ngày nhận và hướng dẫn chăm shop gửi kèm. Vài tháng sau, khi cây có vấn đề, những thông tin này giúp bạn (hoặc người tư vấn) biết cây đã được chăm thế nào, giống gì. Lưu một album riêng trong điện thoại cho \"vườn nhà\" cũng là cách vui để theo dõi cây lớn lên."},{"type":"h2","text":"🔁 Khi nào thì liên hệ shop?"},{"type":"list","items":["Cây gãy thân, gãy ngọn chính, bầu đất vỡ nặng.","Cây sai loại, sai cỡ so với đơn đặt.","Sau 1–2 tuần chăm đúng cách mà cây vẫn tiếp tục xấu đi rõ rệt."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây rụng lá sau khi nhận có phải cây bệnh?"},{"type":"p","text":"Thường là sốc môi trường. Xem [rụng lá do sốc môi trường](/benh-cay/rung-la-soc-moi-truong). Giữ chỗ đặt ổn định, cây sẽ ra lá mới."},{"type":"h3","text":"Cây cảnh có giao được đi xa không?"},{"type":"p","text":"Phần lớn cây kiểng lá, cây cỡ nhỏ và vừa giao xa được nếu đóng gói kỹ. Cây lớn, cây đang ra hoa dễ hư hại hơn — nên hỏi shop trước."},{"type":"h3","text":"Đặt sỉ cho công trình thì nhận hàng thế nào?"},{"type":"p","text":"Nên kiểm đếm, kiểm tra ngẫu nhiên cây theo lô ngay lúc nhận và tưới sớm. Liên hệ [báo giá sỉ](/bao-gia-si) để được tư vấn vận chuyển."},{"type":"p","text":"Xem thêm [cách chọn cây khỏe khi mua](/goc-cham-cay/cach-chon-cay-khoe-khi-mua) và [chăm cây mới mua về](/goc-cham-cay/cham-soc-cay-moi-mua-ve)."}]$j$, 4, ARRAY[$j$rung-la-soc-moi-truong$j$]::text[], ARRAY[$j$mua cây online$j$,$j$giao hàng$j$,$j$cây mới mua$j$]::text[], $j$Hướng dẫn kiểm tra cây cảnh khi nhận hàng giao xa: mở thùng, chụp ảnh, kiểm tra rễ lá sâu bệnh, cách chăm cây trong tuần đầu để cây không sốc.$j$, $j$2026-11-22 07:30:00+07$j$),
($j$cay-rung-la-hang-loat-sau-khi-doi-cho$j$, $j$bat-benh$j$, $j$🐛 Cây rụng lá hàng loạt sau khi mua về hoặc đổi chỗ: sốc môi trường và cách giúp cây hồi phục$j$, $j$Cây rụng lá hàng loạt vài ngày sau khi mua về hay đổi chỗ thường là do sốc môi trường: ánh sáng, nhiệt độ, độ ẩm thay đổi đột ngột. Giữ chỗ đặt ổn định, đủ sáng, tưới vừa phải, không bón phân, không thay chậu; cây thường ra lá mới sau vài tuần.$j$, $j$[{"type":"p","text":"Mua chậu cây đẹp về nhà, vài hôm sau lá vàng rồi rụng lả tả. Hoặc chỉ dời cây từ ban công vào phòng khách, cây đã \"dỗi\" rụng lá. Đây là hiện tượng **sốc môi trường** — rất thường gặp, nhất là với các cây lá nhỏ, cây quen nắng."},{"type":"h2","text":"🔎 Vì sao cây rụng lá khi đổi chỗ?"},{"type":"list","items":["**Ánh sáng giảm đột ngột**: từ nhà vườn nhiều nắng vào phòng tối, cây bỏ bớt lá không nuôi nổi.","**Nhiệt độ, độ ẩm khác**: phòng máy lạnh khô và lạnh hơn ngoài trời.","**Gió lùa, quạt thổi thẳng**.","**Rễ bị xáo trộn** khi vận chuyển, thay chậu."],"ordered":false},{"type":"p","text":"Xem thêm trong thư viện bệnh: [rụng lá do sốc môi trường](/benh-cay/rung-la-soc-moi-truong)."},{"type":"h2","text":"🧭 Sốc môi trường hay nguyên nhân khác?"},{"type":"table","rows":[["Dấu hiệu","Sốc môi trường","Thối rễ","Sâu hại (nhện, rệp)"],["Thời điểm","Vài ngày sau khi đổi chỗ","Từ từ, sau thời gian tưới nhiều","Bất cứ lúc nào, hay mùa khô"],["Lá rụng","Lá còn xanh hoặc hơi vàng","Lá vàng từ dưới lên, mềm","Lá lấm tấm, có tơ, có con"],["Đất","Bình thường","Ẩm lâu, có mùi","Bình thường"],["Đọt non","Vẫn còn sống","Có thể thâm, héo","Xoăn, biến dạng"]]},{"type":"p","text":"Nếu đất có mùi, rễ thâm, xem [thối rễ](/benh-cay/thoi-re); nếu mặt dưới lá có tơ mảnh và chấm nhỏ, xem [nhện đỏ](/benh-cay/nhen-do)."},{"type":"h2","text":"🛠️ Giúp cây hồi phục"},{"type":"list","items":["**Chọn một chỗ đặt và giữ nguyên** — không dời qua dời lại.","Chỗ đó phải đủ sáng cho loại cây (gần cửa sổ, sáng tán xạ).","Tưới khi mặt đất khô 2–3cm; không tưới bù vì thấy cây rụng lá.","Không bón phân, không thay chậu trong 2–3 tuần.","Tránh gió máy lạnh, quạt thổi thẳng vào cây.","Nhặt lá rụng hằng ngày để chậu sạch, dễ theo dõi."],"ordered":true},{"type":"h2","text":"🌿 Cây nào dễ bị sốc?"},{"type":"table","rows":[["Mức độ","Ví dụ"],["Rất dễ rụng lá khi đổi chỗ","Cây lá nhỏ như sanh, si, nguyệt quế; cây quen nắng nhà vườn"],["Trung bình","Đuôi công, lan ý, dương xỉ (dễ cháy mép, rũ)"],["Ít bị","Lưỡi hổ, ngọc ngân, trầu bà đế vương, ngân hậu"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Với cây mua để đặt trong nhà, hỏi nhà vườn cây đã được \"thuần\" dưới lưới che hay chưa. Cây đã quen bóng ít bị sốc hơn hẳn."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Thấy rụng lá là đổi chỗ khác**: mỗi lần đổi là một lần sốc mới.","**Tưới thêm, bón thêm** để \"cứu\": rễ đang yếu dễ úng, cháy.","**Cắt sạch lá còn lại**: cây mất nguồn quang hợp."],"ordered":false},{"type":"h2","text":"🚶 Đổi chỗ cây từ từ"},{"type":"p","text":"Khi muốn chuyển cây từ ban công vào trong nhà (hoặc ngược lại), hãy làm theo nhiều bước nhỏ thay vì một lần. Ví dụ: đặt cây ở chỗ hơi tối hơn một chút trong 1 tuần, sau đó mới chuyển vào vị trí cuối cùng. Mỗi bước, cây có thời gian điều chỉnh lá cho hợp với mức sáng mới, nên rụng ít lá hơn hẳn."},{"type":"h2","text":"🧾 Ghi lại để biết cây có tiến triển"},{"type":"table","rows":[["Ngày","Ghi chú mẫu"],["Ngày 1","Đặt cạnh cửa sổ hướng Đông, rụng 6 lá"],["Ngày 7","Rụng thêm 3 lá, đất còn hơi ẩm"],["Ngày 14","Không rụng thêm, đọt nhú 2 lá non"],["Ngày 21","Lá non mở ra, xanh đều — cây đã quen chỗ"]]},{"type":"p","text":"Ghi vài dòng như vậy giúp bạn bình tĩnh hơn và không vội đổi chỗ cây liên tục."},{"type":"h2","text":"🌬️ Những \"cú sốc\" hay bị bỏ qua"},{"type":"list","items":["Bật máy lạnh trở lại sau nhiều ngày tắt (nghỉ lễ).","Mở cửa sổ gió mùa khô thổi mạnh vào cây.","Phun thuốc, phun phân bón lá ngay sau khi đổi chỗ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bao lâu thì cây hết sốc?"},{"type":"p","text":"Thường 2–4 tuần, tùy loại cây và chỗ đặt mới. Dấu hiệu tốt là đọt nhú lá non."},{"type":"h3","text":"Cây rụng hết lá có còn sống không?"},{"type":"p","text":"Có thể còn. Cạo nhẹ vỏ cành: lớp dưới còn xanh là cành sống. Giữ cây ở chỗ sáng, tưới vừa phải và chờ."},{"type":"h3","text":"Làm sao để cây mới mua ít bị sốc?"},{"type":"p","text":"Xem [kiểm tra và chăm cây khi nhận hàng giao xa](/goc-cham-cay/kiem-tra-cay-khi-nhan-hang-giao-xa) và [chăm cây mới mua về](/goc-cham-cay/cham-soc-cay-moi-mua-ve)."},{"type":"p","text":"Xem thêm [lá cây bị vàng do đâu](/goc-cham-cay/la-cay-bi-vang-nguyen-nhan) và [thư viện bệnh cây](/benh-cay)."}]$j$, 4, ARRAY[$j$rung-la-soc-moi-truong$j$,$j$thoi-re$j$,$j$nhen-do$j$]::text[], ARRAY[$j$rụng lá$j$,$j$cây mới mua$j$,$j$sốc môi trường$j$]::text[], $j$Cây rụng lá hàng loạt sau khi mua về, đổi chỗ: nhận biết sốc môi trường, phân biệt với thối rễ, sâu bệnh và cách giúp cây hồi phục nhanh.$j$, $j$2026-11-23 07:30:00+07$j$),
($j$cat-tia-hoa-giay-ra-hoa-ro-don-tet$j$, $j$cham-soc$j$, $j$🌿 Cắt tỉa, xiết nước cho cây hoa giấy (bông giấy) ra hoa rộ: làm lúc nào, làm thế nào cho đúng$j$, $j$Hoa giấy ra hoa nhiều khi được đủ nắng, cắt tỉa đúng lúc và hơi thiếu nước. Tỉa cành sau đợt hoa, để cành mới mọc rồi giảm tưới cho lá hơi rũ, kết hợp bón phân nhiều lân kali; cây thường ra hoa đồng loạt sau vài tuần.$j$, $j$[{"type":"p","text":"Hoa giấy (bông giấy) là cây quen thuộc trên ban công, cổng nhà ở miền Tây: chịu nắng, chịu hạn, hoa rực rỡ. Nhưng nhiều nhà than cây chỉ ra lá xanh um mà không ra hoa. Bí quyết nằm ở ba thứ: **nắng, cắt tỉa và \"xiết nước\"**."},{"type":"h2","text":"🔎 Vì sao hoa giấy chỉ ra lá?"},{"type":"list","items":["**Thiếu nắng**: hoa giấy cần nắng trực tiếp nhiều giờ mỗi ngày.","**Tưới quá nhiều, bón nhiều đạm**: cây ưu tiên ra cành lá.","**Không cắt tỉa**: cành già, ít cành non — mà hoa thường ra trên cành mới.","**Chậu quá to so với cây**: cây mải phát triển rễ, lá."],"ordered":false},{"type":"h2","text":"✂️ Cắt tỉa đúng lúc"},{"type":"list","items":["Tỉa **ngay sau khi đợt hoa tàn**: cắt ngắn các cành dài, cành mọc lộn xộn.","Cắt bỏ cành khô, cành sâu bệnh, cành mọc vào trong tán.","Bón phân hữu cơ, tưới bình thường để cây ra cành mới.","Khi cành mới đã dài và lá ổn định (thường vài tuần), chuyển sang giai đoạn xiết nước."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Đeo găng tay khi tỉa: nhiều giống hoa giấy có gai cứng ở nách lá."},{"type":"h2","text":"💧 Xiết nước: làm thế nào cho an toàn?"},{"type":"p","text":"Xiết nước là giảm tưới để cây \"cảm thấy\" điều kiện khô hạn và chuyển sang ra hoa. Làm quá tay thì cây rụng lá, khô cành."},{"type":"table","rows":[["Bước","Cách làm"],["Ngày 1–5","Ngưng tưới cho tới khi lá hơi rũ vào buổi trưa"],["Khi lá rũ","Tưới một lượng vừa phải, rồi lại chờ lá hơi rũ mới tưới tiếp"],["Lặp lại","Trong khoảng 1–2 tuần, đến khi thấy nhú lá bắc màu ở đầu cành"],["Khi đã ra hoa","Tưới đều trở lại để hoa bền màu"]]},{"type":"p","text":"Cây trồng đất khó xiết nước hơn cây trồng chậu, vì rễ ăn sâu. Cây trồng đất thường chỉ cần đủ nắng và tỉa cành đúng lúc."},{"type":"h2","text":"🧪 Bón phân hỗ trợ ra hoa"},{"type":"list","items":["Giai đoạn ra cành: phân hữu cơ hoai, phân NPK cân đối liều nhẹ.","Giai đoạn chuẩn bị ra hoa: chuyển sang phân có **lân, kali** cao hơn đạm, theo hướng dẫn trên bao.","Không bón đạm nhiều khi đang muốn cây ra hoa."],"ordered":false},{"type":"p","text":"Xem cách đọc bao phân ở bài [đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."},{"type":"h2","text":"🐛 Sâu bệnh hay gặp trên hoa giấy"},{"type":"list","items":["**Sâu ăn lá**: lá khuyết, có phân đen — bắt tay, xem [sâu ăn lá](/benh-cay/sau-an-la).","**Rệp sáp**: mảng trắng ở nách lá, đọt non — xem [rệp sáp](/benh-cay/rep-sap).","**Bọ phấn trắng**: bay tung khi lay cây — xem [bọ phấn trắng](/goc-cham-cay/bo-phan-trang-tren-cay-canh-rau)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Xiết nước khi cây vừa tỉa xong**: cây chưa có cành mới để ra hoa.","**Để cây héo khô hẳn**: rụng sạch lá, cành chết khô.","**Đặt chậu ở chỗ ít nắng**: không kỹ thuật nào bù được thiếu nắng.","**Thay chậu to ngay trước mùa hoa**: cây lo ra rễ."],"ordered":false},{"type":"h2","text":"🌸 Hoa giấy nhiều màu, chăm có khác nhau?"},{"type":"p","text":"Hoa giấy có nhiều màu: hồng, tím, đỏ, trắng, cam, vàng và cả loại ghép nhiều màu trên một gốc. Cách chăm cơ bản giống nhau: nhiều nắng, đất thoát nước, tỉa cành và xiết nước. Một số giống lá đốm, giống ngoại thường lớn chậm và yếu hơn giống ta, nên bón nhẹ hơn và xiết nước nhẹ tay. Với cây ghép nhiều màu, chú ý tỉa bỏ chồi mọc từ gốc ghép để không lấn át các nhánh ghép."},{"type":"h2","text":"🪴 Hoa giấy trồng chậu hay trồng đất?"},{"type":"table","rows":[["","Trồng chậu","Trồng đất"],["Điều khiển ra hoa","Dễ — xiết nước nhanh có tác dụng","Khó hơn — rễ sâu"],["Sức sống","Phụ thuộc người chăm","Khỏe, chịu hạn tốt"],["Tưới","Thường xuyên hơn mùa khô","Ít khi cần khi cây đã lớn"],["Phù hợp","Ban công, sân thượng, bonsai","Cổng nhà, hàng rào, giàn"]]},{"type":"h2","text":"🌿 Uốn dáng giàn, cổng"},{"type":"p","text":"Hoa giấy có thể làm giàn cổng, giàn hiên. Buộc dây nhẹ hướng cành theo khung khi cành còn non, mềm. Cắt bỏ cành mọc ngược vào trong và cành quá dài vượt khung. Giàn càng thoáng nắng thì hoa càng phủ đều."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bao lâu sau xiết nước thì hoa giấy ra hoa?"},{"type":"p","text":"Thường sau vài tuần, tùy giống, độ nắng và sức cây. Dấu hiệu sớm là lá bắc màu nhú ở đầu cành."},{"type":"h3","text":"Hoa giấy rụng lá khi xiết nước có sao không?"},{"type":"p","text":"Rụng vài lá già là bình thường. Rụng nhiều, cành khô là đã xiết quá tay — tưới lại vừa phải."},{"type":"h3","text":"Muốn hoa giấy nở đúng Tết thì làm gì?"},{"type":"p","text":"Tính ngược thời gian: tỉa cành sớm để cây kịp ra cành mới, rồi xiết nước khoảng một tháng trước Tết. Mỗi cây phản ứng khác nhau nên nên ghi lại để rút kinh nghiệm năm sau."},{"type":"p","text":"Xem thêm [cây cho ban công nắng gắt](/goc-cham-cay/cay-ban-cong-nang-gat) và [lịch chăm cây 12 tháng miền Tây](/goc-cham-cay/lich-cham-cay-12-thang-mien-tay)."}]$j$, 4, ARRAY[$j$rep-sap$j$,$j$sau-an-la$j$]::text[], ARRAY[$j$hoa giấy$j$,$j$bông giấy$j$,$j$ra hoa$j$]::text[], $j$Cách cắt tỉa và xiết nước cho cây hoa giấy (bông giấy) ra hoa rộ: thời điểm tỉa, cách giảm tưới, bón phân, đặt nắng và những lỗi khiến hoa giấy chỉ ra lá.$j$, $j$2026-11-24 07:30:00+07$j$),
($j$trong-ca-tim-trong-chau$j$, $j$rau-sach$j$, $j$🥬 Trồng cà tím trong chậu, thùng xốp: từ cây con đến trái đầu tiên chỉ trong khoảng 2 tháng$j$, $j$Cà tím ưa nắng nóng, trồng chậu sâu 30cm trở lên vẫn cho trái đều. Cấy cây con khỏe, cắm cọc đỡ, tưới đều, bón phân hữu cơ định kỳ và tăng kali khi ra hoa; tỉa lá già, nhánh gốc cho thoáng để giảm bệnh và trái to hơn.$j$, $j$[{"type":"p","text":"Cà tím (cà dái dê) nướng mỡ hành, xào tỏi là món dân dã ngon cơm. Cây chịu nắng nóng tốt, ít kén đất, lại cho trái kéo dài nhiều tháng — rất hợp trồng chậu ở sân thượng, ban công nắng của nhà phố miền Tây."},{"type":"h2","text":"🌱 Gieo hạt hay mua cây con?"},{"type":"p","text":"Người mới nên **mua cây con** khỏe ở cửa hàng giống: cây cao 10–15cm, có 4–6 lá thật, thân mập, lá xanh không đốm. Gieo hạt cũng được nhưng cần ươm trong khay khoảng 3–4 tuần rồi mới cấy."},{"type":"h2","text":"🪴 Chậu, đất, chỗ đặt"},{"type":"list","items":["Chậu hoặc thùng sâu **30cm trở lên**, mỗi chậu 1 cây (thùng xốp lớn trồng 2 cây).","Đất tơi giàu mùn: đất thịt + phân chuồng hoai hoặc phân trùn quế + xơ dừa, trấu hun.","Nắng trực tiếp 6 giờ/ngày trở lên.","Cắm cọc đỡ ngay khi trồng để không làm đứt rễ về sau."],"ordered":false},{"type":"h2","text":"💧 Tưới và bón"},{"type":"table","rows":[["Giai đoạn","Tưới","Bón"],["Mới cấy (1–2 tuần)","Giữ ẩm đều, che nắng trưa 2–3 ngày","Chưa bón"],["Phát triển thân lá","Mỗi ngày, ngày nắng gắt tưới 2 lần","Phân hữu cơ 10–15 ngày/lần"],["Ra hoa, nuôi trái","Tưới đều, không để khô kiệt","Tăng phân có kali, giảm đạm"]]},{"type":"h2","text":"✂️ Tỉa nhánh, tỉa lá"},{"type":"list","items":["Tỉa các nhánh mọc sát gốc, chừa 2–3 nhánh chính khỏe.","Cắt bỏ lá già vàng ở gốc cho thông thoáng.","Hoa cà tím có thể tự thụ phấn; lắc nhẹ cây vào buổi sáng giúp đậu trái tốt hơn khi ít gió, ít côn trùng."],"ordered":false},{"type":"h2","text":"🐛 Sâu bệnh thường gặp"},{"type":"table","rows":[["Vấn đề","Dấu hiệu","Xử lý"],["Nhện đỏ","Lá lấm tấm vàng, có tơ mảnh mặt dưới","Phun nước mặt dưới lá — [nhện đỏ](/benh-cay/nhen-do)"],["Bọ trĩ","Lá, trái có vệt bạc, sần","[Bọ trĩ](/benh-cay/bo-tri)"],["Sâu đục trái","Trái có lỗ, đọt héo rũ","Cắt bỏ đọt, trái bị hại, tiêu hủy"],["Héo xanh","Cây héo đột ngột khi lá còn xanh","Nhổ bỏ — [héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan)"]]},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Cà tím là rau ăn trái: ưu tiên bắt tay, cắt bỏ phần bị hại, bẫy dính. Nếu dùng thuốc, chọn thuốc có đăng ký, đọc kỹ nhãn và chỉ hái sau thời gian cách ly. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."},{"type":"h2","text":"🍆 Thu hoạch"},{"type":"p","text":"Thường khoảng 50–70 ngày sau khi cấy là có trái đầu, tùy giống. Hái khi trái căng bóng, vỏ còn láng, ấn nhẹ thấy đàn hồi. Trái để già vỏ xỉn, hạt cứng, ăn xốp. Hái đều đặn để cây tiếp tục ra hoa."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chậu nhỏ, đất cạn**: cây còi, ít trái.","**Không cắm cọc**: cây đổ khi mang nhiều trái.","**Tưới thất thường**: hoa rụng, trái nhỏ.","**Trồng cà liên tục ở cùng một chỗ đất**: dễ tích mầm bệnh héo xanh."],"ordered":false},{"type":"h2","text":"🌱 Chọn giống cà tím"},{"type":"table","rows":[["Giống","Đặc điểm","Ghi chú"],["Cà tím dài","Trái dài, vỏ tím bóng","Phổ biến, hợp nướng, xào"],["Cà tím tròn","Trái tròn to","Cần chậu lớn hơn"],["Cà pháo, cà dĩa","Trái nhỏ, nhiều trái","Hợp chậu, ăn sống hoặc muối"]]},{"type":"h2","text":"♻️ Cắt tỉa trẻ hóa cây già"},{"type":"p","text":"Sau vài tháng cho trái, cây cà tím thường ra trái nhỏ dần, lá già nhiều. Thay vì nhổ bỏ, có thể cắt bớt khoảng một phần ba các cành già, giữ lại thân chính và vài cành khỏe, sau đó bón phân hữu cơ, tưới đều. Cây sẽ ra lứa cành mới và có thể cho thêm một đợt trái. Cách này hợp với cây vẫn còn khỏe, không bị bệnh héo."},{"type":"h2","text":"🍳 Thu hoạch đúng độ"},{"type":"list","items":["Dùng kéo cắt cuống, chừa một đoạn cuống ngắn trên trái — không giật tay làm gãy cành.","Trái non để được vài ngày trong ngăn mát.","Trái để già trên cây làm cây yếu và giảm số trái mới."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cà tím trồng chậu sống được bao lâu?"},{"type":"p","text":"Chăm tốt, cây có thể cho trái nhiều tháng. Khi cây già, trái nhỏ dần, có thể cắt bớt cành, bón phân để cây ra lứa mới hoặc trồng cây mới."},{"type":"h3","text":"Vì sao cà tím ra hoa mà không đậu trái?"},{"type":"p","text":"Thường do nắng nóng gay gắt, thiếu nước, bón dư đạm hoặc thiếu thụ phấn. Tưới đều, giảm đạm, lắc nhẹ cây buổi sáng."},{"type":"h3","text":"Có nên dùng đất cũ trồng cà chua để trồng cà tím?"},{"type":"p","text":"Không nên, vì cà chua, ớt, cà tím cùng họ, dễ chung mầm bệnh. Nên thay hoặc xử lý đất trước."},{"type":"p","text":"Trồng thêm: [cà chua chậu](/goc-cham-cay/trong-ca-chua-chau), [ớt chậu](/goc-cham-cay/trong-ot-chau), [dưa leo sân thượng](/goc-cham-cay/trong-dua-leo-san-thuong)."}]$j$, 4, ARRAY[$j$heo-xanh-vi-khuan$j$,$j$nhen-do$j$,$j$bo-tri$j$]::text[], ARRAY[$j$cà tím$j$,$j$rau sạch$j$,$j$trồng chậu$j$]::text[], $j$Cách trồng cà tím trong chậu, thùng xốp tại nhà: chọn giống, đất, cấy cây con, cắm cọc, tưới bón, tỉa nhánh, phòng sâu bệnh và thu hoạch.$j$, $j$2026-11-25 07:30:00+07$j$),
($j$bon-phan-cay-hoa-truoc-tet$j$, $j$thuoc-phan-bon$j$, $j$🧪 Bón phân cho cây hoa trước Tết: giai đoạn nào bón gì để nụ chắc, hoa bền màu$j$, $j$Cây hoa chưng Tết cần bón theo giai đoạn: đầu mùa khô bón phân hữu cơ và NPK cân đối để cây khỏe; khi cây chuẩn bị ra nụ chuyển sang phân nhiều lân, kali; khi nụ đã lớn thì giảm bón, tránh đạm để hoa không bị lá lấn át.$j$, $j$[{"type":"p","text":"Mai vàng, hoa giấy, cúc, hoa hồng hay mai địa thảo muốn nở đẹp dịp Tết đều cần được \"nuôi\" từ trước đó nhiều tuần. Bón đúng loại phân **đúng giai đoạn** quan trọng hơn bón nhiều."},{"type":"h2","text":"📅 Ba giai đoạn bón phân"},{"type":"table","rows":[["Giai đoạn","Mục tiêu","Loại phân gợi ý"],["Hồi sức (sau mưa, trước Tết 2–3 tháng)","Cây khỏe, ra cành lá mới","Phân hữu cơ hoai, NPK cân đối"],["Chuẩn bị ra nụ (trước Tết khoảng 1–2 tháng)","Phân hóa mầm hoa","Phân nhiều lân, kali; giảm đạm"],["Nuôi nụ (nụ đã rõ)","Nụ chắc, hoa bền màu","Liều nhẹ phân có kali; nhiều cây không cần bón thêm"],["Khi đang chưng","Giữ hoa","Không bón — chỉ tưới đều"]]},{"type":"p","text":"Mốc thời gian chỉ là tham khảo; mỗi loại cây, mỗi giống phản ứng khác nhau. Cây mua sẵn từ nhà vườn thường đã được bón đủ cho đợt hoa."},{"type":"h2","text":"📖 Đọc bao phân: chọn loại \"ra hoa\""},{"type":"p","text":"Ba số trên bao phân là tỷ lệ đạm (N) – lân (P) – kali (K). Phân cho giai đoạn ra hoa thường có số giữa (lân) hoặc số cuối (kali) cao hơn số đầu (đạm). Xem cách đọc chi tiết ở bài [đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."},{"type":"h2","text":"🧪 Cách bón an toàn cho cây chậu"},{"type":"list","items":["Tưới ẩm đất trước khi bón — không bón khi đất khô kiệt.","Pha hoặc rải **đúng liều hướng dẫn**, cây chậu nên dùng liều nhẹ hơn.","Rải phân cách gốc, theo vòng tán, xới nhẹ lấp phân.","Tưới lại sau khi bón để phân tan và ngấm đều.","Chia nhỏ nhiều lần thay vì bón đậm một lần."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Đeo găng tay khi bón phân hóa học, rửa tay sau khi dùng, cất phân xa tầm tay trẻ nhỏ và thú cưng, không để chung với thực phẩm."},{"type":"h2","text":"🌸 Gợi ý theo loại cây"},{"type":"table","rows":[["Cây","Lưu ý khi bón"],["Mai vàng","Bón lân, kali trước khi lặt lá; không bón đạm sau lặt"],["Hoa giấy","Giảm đạm, kết hợp xiết nước — xem [cắt tỉa hoa giấy ra hoa rộ](/goc-cham-cay/cat-tia-hoa-giay-ra-hoa-ro-don-tet)"],["Cúc","Cúc mua về đã được bón; trong Tết chỉ tưới"],["Hoa hồng","Bón định kỳ sau mỗi đợt cắt hoa, phân có trung vi lượng"],["Mai địa thảo","Bón nhẹ thường xuyên, ra hoa quanh năm"]]},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Bón đạm nhiều cho \"cây tốt\"** ngay trước Tết: cây ra lá, nụ ít.","**Bón đậm một lần**: cháy rễ, lá cháy mép — xem [cháy rễ do bón phân](/benh-cay/chay-re-do-phan).","**Bón khi cây đang yếu, rễ hỏng**: phân làm rễ hỏng thêm.","**Phun phân bón lá giữa trưa**: cháy lá."],"ordered":false},{"type":"h2","text":"🍂 Phân hữu cơ: nền tảng cho cây hoa"},{"type":"p","text":"Trước khi nghĩ tới phân \"kích hoa\", hãy chắc rằng đất đủ tơi xốp và giàu mùn. Phân hữu cơ hoai mục, phân trùn quế giúp đất giữ nước, giữ dinh dưỡng và nuôi hệ vi sinh có ích. Cây có bộ rễ khỏe thì hút phân lân, kali hiệu quả hơn. Bón phân hữu cơ vào giai đoạn hồi sức (đầu mùa khô), sau đó mới dùng phân hóa học bổ sung theo giai đoạn. Xem [phân hữu cơ cho cây cảnh](/goc-cham-cay/phan-huu-co-cho-cay-canh)."},{"type":"h2","text":"📏 Ước lượng liều cho cây chậu"},{"type":"table","rows":[["Cỡ chậu (đường kính)","Gợi ý"],["Dưới 20cm","Liều rất nhẹ, pha loãng hơn hướng dẫn; ưu tiên phân tan chậm"],["20–40cm","Theo liều hướng dẫn cho cây chậu, chia 2–3 lần"],["Trên 40cm, cây lớn","Theo hướng dẫn, rải đều vòng tán"]]},{"type":"p","text":"Khi không chắc, bón ít hơn một chút luôn an toàn hơn bón dư. Cây thiếu phân có thể bổ sung sau; cây cháy rễ thì rất khó cứu."},{"type":"h2","text":"🌧️ Thời tiết ảnh hưởng tới bón phân"},{"type":"list","items":["Không bón ngay trước cơn mưa lớn: phân bị rửa trôi.","Trời nắng gắt, đất khô: tưới ẩm trước rồi mới bón.","Trời âm u kéo dài: cây hút ít, giảm liều."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Phân bón lá có giúp ra hoa nhanh không?"},{"type":"p","text":"Phân bón lá có tác dụng nhanh, hữu ích khi cây cần bổ sung vi lượng. Nhưng nền dinh dưỡng chính vẫn đến từ bón gốc. Xem [phân bón lá và phân bón gốc](/goc-cham-cay/phan-bon-la-va-phan-bon-goc)."},{"type":"h3","text":"Phân hữu cơ có đủ cho cây ra hoa không?"},{"type":"p","text":"Phân hữu cơ giúp đất tốt, cây khỏe lâu dài. Với cây hoa cần ra rộ đúng dịp, nhiều người kết hợp thêm phân có lân, kali."},{"type":"h3","text":"Phân tan chậm có hợp cây hoa chậu không?"},{"type":"p","text":"Hợp, đặc biệt với người bận rộn. Xem [phân tan chậm và phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan)."},{"type":"products","title":"Dùng trong bài này","slugs":["mai-dia-thao","hoa-hong"]}]$j$, 4, ARRAY[$j$chay-re-do-phan$j$]::text[], ARRAY[$j$phân bón$j$,$j$cây Tết$j$,$j$ra hoa$j$]::text[], $j$Cách bón phân cho cây hoa trước Tết theo từng giai đoạn: hồi sức, chuẩn bị ra nụ, nuôi nụ; chọn phân nhiều lân kali, liều lượng và lỗi thường gặp.$j$, $j$2026-11-26 07:30:00+07$j$),
($j$cay-xanh-cho-quan-ca-phe-cua-hang$j$, $j$cam-nang$j$, $j$📗 Cây xanh cho quán cà phê, cửa hàng: chọn cây theo vị trí, ngân sách và công chăm sóc$j$, $j$Quán cà phê, cửa hàng nên chọn cây theo từng vị trí: cây chịu nắng cho mặt tiền, cây chịu bóng cho bên trong, cây treo cho tường và trần. Ưu tiên cây bền, ít rụng lá, ít côn trùng; lập lịch chăm và dùng chậu có đĩa lót để giữ quán sạch.$j$, $j$[{"type":"p","text":"Một quán cà phê nhiều cây xanh luôn tạo cảm giác mát mẻ, thư giãn và dễ \"lên hình\". Nhưng cây trong quán phải chịu nhiều thứ: nắng mặt tiền, máy lạnh, khách qua lại, nhân viên thay ca. Chọn đúng cây ngay từ đầu giúp quán **đẹp lâu mà ít tốn công**."},{"type":"h2","text":"📍 Chọn cây theo vị trí"},{"type":"table","rows":[["Vị trí","Điều kiện","Gợi ý"],["Mặt tiền, vỉa hè","Nắng gắt, bụi, gió","Cau trắng, bàng Đài Loan, mai địa thảo, hoa giấy"],["Cửa ra vào","Sáng, người qua lại nhiều","Cây dáng đứng gọn: lưỡi hổ, trầu bà đế vương"],["Bên trong có máy lạnh","Sáng yếu, khô","Ngân hậu, bạch mã, trầu bà, lưỡi hổ"],["Quầy pha chế, quầy thu ngân","Chật, nhiều đồ","Cây nhỏ để bàn: ngọc ngân, lan chi"],["Tường, trần, cửa sổ","Nhiều sáng tán xạ","Cây treo: lan chi, trầu bà rủ, dương xỉ"]]},{"type":"h2","text":"✅ Tiêu chí chọn cây cho nơi kinh doanh"},{"type":"list","items":["**Bền, ít rụng lá**: đỡ công quét dọn, quán luôn sạch.","**Không gai, không nhựa độc ở chỗ thấp**: khách có trẻ nhỏ.","**Ít côn trùng**: tránh đất ẩm sinh ruồi nấm quanh bàn khách.","**Dễ thay thế**: chọn loại phổ biến, khi cây xấu dễ mua cây cùng loại."],"ordered":false},{"type":"h2","text":"🗓️ Lịch chăm cho nhân viên"},{"type":"table","rows":[["Tần suất","Việc"],["Mỗi ngày (mở quán)","Nhặt lá rụng, xem cây có héo không"],["Mỗi tuần","Kiểm tra đất, tưới; đổ nước đọng dưới đĩa"],["2 tuần","Lau lá, kiểm tra sâu bệnh, xoay chậu"],["Mỗi tháng","Bón phân nhẹ, luân phiên cây trong nhà ra chỗ sáng"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Giao cho một nhân viên phụ trách chính và dán lịch ở khu vực quầy. Cây chết ở quán thường do mỗi ca tưới một lần, chứ không phải do thiếu chăm."},{"type":"h2","text":"💰 Tính chi phí"},{"type":"p","text":"Chi phí ban đầu gồm cây, chậu, đất, phụ kiện. Chi phí duy trì gồm phân bón, thay cây hư, công chăm. Mua cây số lượng lớn cùng lúc, cùng một nhà vườn thường giúp cây đồng đều và có giá tốt hơn — xem [gửi yêu cầu báo giá sỉ](/bao-gia-si)."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt cây chịu bóng ở mặt tiền nắng gắt**: cháy lá sau vài ngày.","**Chậu không có đĩa lót**: nước tưới chảy ra sàn, khách trượt ngã.","**Để khách gạt tàn, đổ đồ uống vào chậu**: đất chua, có mùi, kiến.","**Trồng quá nhiều cây ở góc tối**: cây xuống dần, quán trông kém tươi."],"ordered":false},{"type":"h2","text":"🎨 Bố trí cây cho đẹp và tiện"},{"type":"list","items":["**Tạo điểm nhấn ở cửa**: một cặp cây đứng cân đối hai bên cửa giúp quán dễ nhận ra từ xa.","**Làm vách ngăn mềm**: dãy chậu cây cao ngăn khu ngồi, tạo không gian riêng tư.","**Góc chụp ảnh**: một mảng tường cây treo, cây leo thường được khách yêu thích.","**Để lối đi thông thoáng**: chậu không lấn lối đi, không vướng nhân viên bưng đồ."],"ordered":false},{"type":"h2","text":"🧽 Giữ cây sạch cho nơi phục vụ đồ ăn uống"},{"type":"p","text":"Quán ăn uống cần sạch sẽ: phủ mặt chậu bằng sỏi, đá trang trí để đất không bắn ra; dùng phân tan chậm dạng viên thay vì phân có mùi; lau lá định kỳ vì bụi đường bám nhiều. Cây có hoa rụng nhiều, cây hay rụng lá nên đặt xa bàn khách. Khi phải xử lý sâu bệnh, làm vào lúc quán đóng cửa và ưu tiên biện pháp không dùng thuốc."},{"type":"h2","text":"🔄 Luân phiên cây trong quán"},{"type":"p","text":"Cây đặt sâu trong quán thiếu sáng sẽ xuống màu sau một thời gian. Nhiều quán có hai bộ cây: một bộ trưng bày, một bộ để ngoài chỗ sáng \"nghỉ dưỡng\", đổi nhau mỗi vài tuần. Cách này giúp quán luôn có cây đẹp mà ít phải mua cây mới."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Có nên dùng cây giả cho quán?"},{"type":"p","text":"Cây giả hợp những góc quá tối, khó chăm. Kết hợp cây thật ở chỗ sáng và cây giả chất lượng tốt ở góc khó giúp quán vừa đẹp vừa đỡ công."},{"type":"h3","text":"Ruồi nhỏ bay quanh chậu cây trong quán phải làm sao?"},{"type":"p","text":"Đó thường là ruồi nấm đất do tưới quá nhiều. Xem [ruồi nhỏ bay quanh chậu cây](/goc-cham-cay/ruoi-nho-bay-quanh-chau-cay)."},{"type":"h3","text":"Cây trong quán có cần thay định kỳ không?"},{"type":"p","text":"Cây chịu bóng trong nhà nên được luân phiên ra chỗ sáng. Cây đã xuống màu nhiều nên thay hoặc đưa về vườn chăm lại."},{"type":"products","title":"Dùng trong bài này","slugs":["cau-trang","bang-dai-loan","luoi-ho","ngan-hau","trau-ba-de-vuong-xanh","lan-chi"]},{"type":"p","text":"Xem thêm [cây văn phòng chịu bóng, ít tưới](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi) và [cây treo, giỏ treo trang trí](/goc-cham-cay/cay-treo-gio-treo-trang-tri)."}]$j$, 4, ARRAY[]::text[], ARRAY[$j$quán cà phê$j$,$j$cửa hàng$j$,$j$cây công trình$j$]::text[], $j$Gợi ý chọn cây xanh cho quán cà phê, cửa hàng: cây mặt tiền chịu nắng, cây trong nhà chịu bóng, cây treo, cách bố trí, chăm sóc và tính chi phí.$j$, $j$2026-11-27 07:30:00+07$j$),
($j$chon-mua-mai-vang-chung-tet$j$, $j$theo-mua$j$, $j$🌦️ Chọn mua mai vàng chưng Tết: xem dáng, nụ, bầu rễ thế nào để mai nở đúng dịp, không rụng nụ$j$, $j$Mua mai vàng chưng Tết nên chọn cây khỏe, thân vỏ láng, bầu đất chắc, nụ nhiều và đều; nụ không quá già cũng không quá non so với ngày Tết. Mang mai về cần đặt chỗ nắng sáng, tưới đều và tránh dời chỗ liên tục để nụ không rụng.$j$, $j$[{"type":"p","text":"Mỗi năm, từ giữa tháng Chạp, các chợ hoa và vườn mai bắt đầu tấp nập. Một cây mai đẹp không chỉ ở dáng thế mà còn ở **sức khỏe của cây và độ \"đúng tuổi\" của nụ**. Chọn sai, mai có thể nở bung trước Tết hoặc đứng nụ tới mùng 5."},{"type":"h2","text":"📅 Nên mua mai lúc nào?"},{"type":"table","rows":[["Thời điểm","Ưu điểm","Lưu ý"],["Đầu tháng Chạp (chưa lặt lá)","Nhiều lựa chọn, tự lặt lá theo ý mình","Cần biết cách lặt và canh ngày"],["Giữa tháng Chạp (vừa lặt)","Nhà vườn đã canh ngày, nụ đang lớn","Hỏi rõ ngày lặt"],["Sát Tết (nụ hé vàng)","Thấy rõ hoa sẽ nở thế nào","Ít lựa chọn; vận chuyển dễ rụng nụ"]]},{"type":"h2","text":"🔍 Xem 5 điểm trên cây"},{"type":"list","items":["**Thân, cành**: vỏ láng, không nứt toác, không có lỗ đục, mủ chảy; cành phân bố đều.","**Bầu đất**: lắc nhẹ gốc, bầu chắc, cây không lung lay; đất không bốc mùi chua.","**Nụ**: nhiều, đều khắp cành, không dồn một phía; vảy nụ căng, không khô đen.","**Lá (nếu chưa lặt)**: xanh đậm, dày, không đốm, không có rệp ở đọt.","**Rễ nổi, gốc**: không có tơ trắng, nấm mốc bao quanh cổ rễ."],"ordered":true},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Hỏi nhà vườn ba câu: lặt lá ngày nào, cây trồng chậu bao lâu, có bón phân gì gần đây. Câu trả lời rõ ràng là dấu hiệu cây được chăm có kế hoạch."},{"type":"h2","text":"🌼 Đọc độ \"chín\" của nụ"},{"type":"table","rows":[["Hình dạng nụ","Dự đoán"],["Nụ nhỏ như hạt tiêu, vảy còn khép chặt","Còn khá lâu mới nở — hợp mua sớm"],["Nụ bằng hạt đậu xanh, vảy căng, bắt đầu tách","Thường nở sau khoảng 1–2 tuần, tùy thời tiết"],["Nụ lộ màu vàng ở đầu","Sắp nở trong vài ngày"],["Nhiều hoa đã nở bung","Đẹp ngay nhưng có thể tàn trước Tết"]]},{"type":"p","text":"Thời gian trên chỉ để tham khảo: trời nóng mai nở nhanh hơn, trời se lạnh nở chậm hơn."},{"type":"h2","text":"🚚 Vận chuyển và chăm khi mang về"},{"type":"list","items":["Bọc nhẹ tán bằng lưới hoặc giấy, buộc cố định chậu, tránh va đập làm rụng nụ.","Về nhà đặt nơi **nắng sáng, thoáng gió**, tránh gió lùa mạnh.","Tưới gốc đều mỗi sáng; không tưới lên nụ, không để chậu khô kiệt.","Hạn chế dời chậu ra vào nhiều lần — mai dễ rụng nụ khi đổi môi trường liên tục.","Chưng trong phòng khách chỉ vài ngày Tết, sau đó mang ra ngoài."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chỉ nhìn dáng, quên nhìn bầu rễ**: cây vừa bứng khỏi đất, rễ yếu, dễ rụng nụ.","**Mua cây nở bung sớm** vì đẹp lúc mua: tới Tết hoa đã tàn.","**Đặt mai cạnh máy lạnh, quạt thổi thẳng**: nụ khô, rụng.","**Bón phân đạm sau khi mua**: cây ra lá non thay vì hoa."],"ordered":false},{"type":"h2","text":"🌳 Dáng mai: chọn theo sở thích và không gian"},{"type":"table","rows":[["Dáng","Đặc điểm","Hợp với"],["Mai tàng (tán tròn)","Tán xòe đều, nhiều hoa","Sân rộng, phòng khách lớn"],["Mai bonsai, dáng thế","Thân uốn, gốc to, dáng nghệ thuật","Người thích chơi cây cảnh"],["Mai cành nhỏ, chậu nhỏ","Gọn, nhẹ","Căn hộ, ban công"],["Mai giảo, mai nhiều cánh","Hoa to, nhiều cánh","Người thích hoa lạ — giá thường cao hơn"]]},{"type":"h2","text":"💰 Giá mai phụ thuộc vào gì?"},{"type":"p","text":"Giá mai vàng thay đổi rất nhiều theo tuổi cây, kích thước gốc, dáng thế, số lượng nụ, giống và thời điểm mua. Mai gốc to, dáng đẹp, nhiều năm tuổi có giá cao. Sát Tết giá thường biến động. Nên tham khảo vài nơi, hỏi rõ giá đã gồm chậu, vận chuyển hay chưa trước khi quyết định."},{"type":"h2","text":"🏠 Đặt mai ở đâu cho đẹp và bền?"},{"type":"list","items":["Mai lớn: sân trước, hiên nhà có nắng sáng.","Chưng phòng khách: chọn vài ngày Tết, sau đó đưa ra ngoài.","Tránh đặt sát lối đi hẹp — cành va chạm làm rụng nụ, hoa."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Mai bị rụng nụ sau khi mua về là do đâu?"},{"type":"p","text":"Thường do sốc khi vận chuyển, thay đổi chỗ đặt, thiếu nước hoặc tưới quá nhiều. Giữ chỗ đặt ổn định, tưới đều, có nắng sáng."},{"type":"h3","text":"Có nên thuê chậu mai chưng Tết?"},{"type":"p","text":"Thuê mai hợp với nhà không có chỗ chăm sau Tết. Hỏi rõ điều kiện chăm và trả cây để tránh phát sinh chi phí."},{"type":"h3","text":"Sau Tết chăm mai thế nào?"},{"type":"p","text":"Cắt bỏ hoa tàn, trái non, tỉa cành, bón phân hữu cơ để cây hồi sức. Xem [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."},{"type":"p","text":"Xem thêm [lặt lá mai vàng trước Tết](/goc-cham-cay/lat-la-mai-vang-truoc-tet) và [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet)."}]$j$, 4, ARRAY[]::text[], ARRAY[$j$mai vàng$j$,$j$cây Tết$j$,$j$chọn cây$j$]::text[], $j$Cách chọn mua mai vàng chưng Tết: xem dáng thế, nụ, bầu rễ, lá; mua mai lặt sẵn hay chưa lặt; chăm mai sau khi mang về để hoa nở đúng Tết.$j$, $j$2026-11-28 07:30:00+07$j$),
($j$tuoi-nho-giot-hen-gio-ban-cong-nghi-tet$j$, $j$cham-soc$j$, $j$💧 Lắp tưới nhỏ giọt hẹn giờ cho ban công, sân thượng: yên tâm về quê ăn Tết cả tuần$j$, $j$Bộ tưới nhỏ giọt hẹn giờ gồm van hẹn giờ, ống dẫn và đầu nhỏ giọt cho từng chậu, tự tưới theo lịch khi bạn đi vắng. Nên lắp và chạy thử trước khi đi ít nhất 1 tuần để chỉnh lượng nước cho từng chậu, tránh chậu úng chậu khô.$j$, $j$[{"type":"p","text":"Tết là dịp nhiều gia đình về quê cả tuần. Cây ban công, sân thượng giữa mùa khô nắng gió thì vài ngày không tưới là héo rũ. **Bộ tưới nhỏ giọt hẹn giờ** là cách chắc chắn nhất để giữ cây khi không nhờ được ai."},{"type":"h2","text":"🧰 Một bộ tưới nhỏ giọt gồm gì?"},{"type":"table","rows":[["Bộ phận","Chức năng"],["Van hẹn giờ (timer)","Gắn vào vòi nước, tự mở/tắt theo lịch"],["Bộ lọc","Chặn cặn bẩn làm tắc đầu nhỏ giọt"],["Ống chính","Dẫn nước dọc khu đặt chậu"],["Ống nhánh + đầu nhỏ giọt","Đưa nước tới từng chậu, chỉnh được lưu lượng"],["Nút bịt, khớp nối, kẹp ống","Cố định đường ống"]]},{"type":"p","text":"Nhà không có vòi nước ở ban công có thể dùng bộ tưới bằng **máy bơm mini đặt trong thùng nước**, có hẹn giờ — thùng càng lớn tưới được càng lâu."},{"type":"h2","text":"🔧 Các bước lắp"},{"type":"list","items":["Xếp các chậu gần nhau theo một hoặc hai hàng.","Gắn van hẹn giờ và bộ lọc vào vòi nước.","Đi ống chính dọc hàng chậu, cố định bằng kẹp.","Đục lỗ, gắn ống nhánh và cắm đầu nhỏ giọt vào từng chậu, gần gốc nhưng không sát thân.","Cài lịch tưới: thường 1–2 lần mỗi ngày vào sáng sớm (và chiều mát nếu nắng gắt)."],"ordered":true},{"type":"h2","text":"🧪 Chạy thử ít nhất 1 tuần trước khi đi"},{"type":"list","items":["Sau mỗi lần tưới, kiểm tra đất từng chậu: chậu nào khô thì tăng lưu lượng, chậu nào sũng thì giảm.","Cây chịu hạn (lưỡi hổ, sen đá) nên tách ra nhánh riêng hoặc không cắm đầu tưới.","Kiểm tra rò rỉ ở khớp nối, nước chảy xuống tầng dưới.","Thay pin van hẹn giờ mới trước khi đi."],"ordered":false},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Chụp ảnh lịch đã cài và nhờ một người hàng xóm biết chỗ khóa nước tổng — phòng khi ống bị bung lúc bạn vắng nhà."},{"type":"h2","text":"🪴 Chuẩn bị thêm cho cây trước khi đi"},{"type":"list","items":["Tưới đẫm cả vườn 1 ngày trước khi đi.","Phủ gốc bằng rơm, xơ dừa để giữ ẩm.","Dời cây lá mỏng khỏi chỗ nắng chiều gắt.","Cây trong nhà: xem cách giữ ẩm bằng bấc vải, khay sỏi ở bài [giữ cây khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Lắp xong đi ngay, không chạy thử**: chậu úng, chậu khô không đều.","**Không lắp bộ lọc**: đầu nhỏ giọt tắc sau vài ngày.","**Cài tưới giữa trưa**: nước nóng trong ống, phí nước.","**Dùng chung một lưu lượng cho mọi cây**."],"ordered":false},{"type":"h2","text":"📏 Ước lượng nước cần dự trữ"},{"type":"p","text":"Với hệ thống dùng thùng nước và bơm mini, cần tính lượng nước đủ cho cả kỳ nghỉ. Cách đơn giản: chạy thử 1 ngày, đo lượng nước thùng bị hao (ví dụ bằng vạch đánh dấu), rồi nhân với số ngày đi vắng, cộng thêm khoảng một phần ba để dự phòng ngày nắng gắt. Nếu thùng không đủ lớn, đặt thêm một thùng phụ hoặc giảm số lần tưới cho cây chịu hạn."},{"type":"h2","text":"🌿 Nhóm cây theo nhu cầu nước"},{"type":"table","rows":[["Nhóm","Ví dụ","Cách đặt đầu tưới"],["Cần nhiều nước","Rau, cúc, hoa giấy chậu nhỏ, dương xỉ","1–2 đầu tưới mỗi chậu"],["Trung bình","Trầu bà, mai địa thảo, cây kiểng lá","1 đầu tưới, lưu lượng vừa"],["Ít nước","Lưỡi hổ, sen đá, ngọc bích","Không cắm hoặc lưu lượng rất nhỏ"]]},{"type":"h2","text":"🔁 Sau kỳ nghỉ"},{"type":"list","items":["Kiểm tra từng chậu: chậu nào úng thì nghiêng đổ nước, chậu khô thì tưới bù vừa phải.","Vệ sinh bộ lọc, đầu nhỏ giọt.","Có thể giữ hệ thống để dùng suốt mùa khô, chỉ cần chỉnh lịch tưới."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Tưới nhỏ giọt có dùng cho cây trong nhà được không?"},{"type":"p","text":"Được, nhưng cần khay hứng nước và chạy thử kỹ để không tràn ra sàn. Cây trong nhà thường cần rất ít nước."},{"type":"h3","text":"Chi phí một bộ tưới nhỏ giọt có đắt không?"},{"type":"p","text":"Bộ cơ bản cho ban công vài chục chậu khá phổ biến và dễ mua ở cửa hàng vật tư nông nghiệp, cửa hàng điện nước. Giá tùy loại van hẹn giờ."},{"type":"h3","text":"Mất điện có ảnh hưởng không?"},{"type":"p","text":"Van hẹn giờ dùng pin không phụ thuộc điện lưới. Máy bơm mini dùng điện thì sẽ dừng khi mất điện."},{"type":"p","text":"Xem thêm [tưới cây bằng nước gì tốt nhất](/goc-cham-cay/tuoi-cay-bang-nuoc-gi-tot) và [chăm cây mùa khô nắng nóng](/goc-cham-cay/cham-cay-mua-kho-nang-nong)."}]$j$, 4, ARRAY[$j$heo-thieu-nuoc$j$,$j$thoi-re$j$]::text[], ARRAY[$j$tưới nhỏ giọt$j$,$j$đi vắng$j$,$j$ban công$j$]::text[], $j$Cách lắp hệ thống tưới nhỏ giọt hẹn giờ cho cây ban công, sân thượng khi về quê ăn Tết: chuẩn bị gì, lắp thế nào, chạy thử, chỉnh lượng nước.$j$, $j$2026-11-29 07:30:00+07$j$),
($j$chung-cay-gi-ngay-tet-y-nghia$j$, $j$phong-thuy$j$, $j$🍀 Chưng cây gì ngày Tết: ý nghĩa mai, đào, quất, cúc, vạn thọ theo quan niệm dân gian$j$, $j$Mỗi loại cây Tết mang một lời chúc theo quan niệm dân gian: mai vàng phú quý, đào bình an, quất (tắc) sung túc, cúc trường thọ, vạn thọ sống lâu. Chọn cây nên hợp chỗ đặt và thời gian chăm, chưng vừa đủ thay vì quá nhiều chậu.$j$, $j$[{"type":"p","text":"Tết miền Nam không thể thiếu chậu mai vàng, cặp tắc trước cửa, chậu cúc mâm xôi ngoài hiên. Mỗi loại cây gắn với một lời chúc. Bài viết tóm tắt ý nghĩa quen thuộc theo quan niệm dân gian và gợi ý bày cây cho hợp không gian."},{"type":"h2","text":"🌼 Ý nghĩa các cây Tết quen thuộc"},{"type":"table","rows":[["Cây","Ý nghĩa dân gian","Hợp với"],["Mai vàng","Phú quý, may mắn, năm mới hưng thịnh","Nhà phố, sân vườn miền Nam"],["Đào","Xua điều xấu, bình an","Phổ biến ở miền Bắc; miền Nam chưng cành"],["Quất / tắc kiểng","Sung túc, trái chín vàng đầy cây","Cặp trước cửa, hiên nhà"],["Cúc mâm xôi","Trường thọ, đầy đặn","Bậc thềm, sân trước"],["Vạn thọ","Sống lâu, bền bỉ","Bàn thờ, trước sân"],["Tùng, tùng thơm","Vững vàng, trường tồn","Phòng khách, tặng người lớn tuổi"],["Mai địa thảo","Hoa nở quanh năm, tươi vui","Bồn hoa, chậu treo"]]},{"type":"p","text":"Đây là quan niệm dân gian, tùy vùng miền và gia đình mà cách hiểu có khác nhau. Không có cơ sở khoa học về việc cây mang lại may mắn."},{"type":"h2","text":"🏠 Bày cây Tết theo không gian"},{"type":"table","rows":[["Không gian","Gợi ý"],["Nhà phố có sân","Mai vàng chậu lớn + cặp tắc ở cổng + cúc dọc lối đi"],["Căn hộ chung cư","1 chậu mai nhỏ hoặc cành mai cắm + chậu cúc trên ban công"],["Cửa hàng, văn phòng","Cặp tắc hoặc mai ở cửa, cây xanh chịu bóng bên trong"],["Bàn thờ","Hoa cúc, vạn thọ chậu nhỏ hoặc cắm bình"]]},{"type":"h2","text":"🧺 Mẹo để cây Tết đẹp suốt mấy ngày Tết"},{"type":"list","items":["Cây hoa (mai, cúc, vạn thọ) cần **nắng sáng**: chưng trong nhà vài ngày rồi đem ra ngoài.","Tưới gốc đều mỗi sáng; giao việc tưới cho một người để khỏi quên trong những ngày bận rộn.","Tắc kiểng: không để chậu khô kiệt — trái dễ rụng.","Ngắt bông tàn mỗi ngày cho chậu luôn gọn."],"ordered":false},{"type":"p","text":"Xem chi tiết: [chăm cúc chưng Tết bền hoa](/goc-cham-cay/cham-cuc-chung-tet-ben-hoa), [chọn mua mai vàng chưng Tết](/goc-cham-cay/chon-mua-mai-vang-chung-tet)."},{"type":"h2","text":"♻️ Sau Tết cây đi đâu?"},{"type":"p","text":"Nhiều chậu cây Tết bị bỏ sau rằm tháng Giêng. Thật ra mai vàng, tắc, tùng có thể giữ lại chăm cho năm sau; cúc, vạn thọ có thể giâm ngọn làm cây con. Nếu không có chỗ chăm, có thể tặng lại cho người thích trồng cây. Xem [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Mua quá nhiều chậu** rồi không đủ chỗ nắng, cây úa ngay giữa Tết.","**Chưng cây hoa trong phòng máy lạnh suốt Tết**.","**Chọn cây chỉ theo ý nghĩa** mà quên chỗ đặt có hợp không."],"ordered":false},{"type":"h2","text":"🍊 Cặp tắc trước cửa: chọn sao cho đẹp"},{"type":"list","items":["Chọn hai cây tương đương nhau về chiều cao, độ tán, lượng trái.","Trái vàng xanh xen kẽ, chín dần sẽ đẹp suốt Tết hơn cây đã chín vàng hết.","Lá xanh bóng, không rụng nhiều khi lắc nhẹ.","Đặt cân đối hai bên cửa, nơi có nắng sáng."],"ordered":false},{"type":"h2","text":"🌺 Những loại hoa Tết khác ngày càng phổ biến"},{"type":"table","rows":[["Hoa","Điểm đặc biệt"],["Lan hồ điệp","Bền hoa nhiều tuần, hợp chưng trong nhà"],["Mai địa thảo","Nhiều màu, ra hoa liên tục"],["Thược dược, cát tường","Màu sắc tươi, hợp bàn thờ, phòng khách"],["Hoa giấy bonsai","Bền, chịu nắng, nhiều màu"]]},{"type":"h2","text":"🧧 Mâm ngũ quả và cây Tết"},{"type":"p","text":"Bên cạnh cây chưng, mâm ngũ quả cũng mang nhiều lời chúc theo quan niệm dân gian miền Nam, như \"cầu vừa đủ xài\" từ mãng cầu, dừa, đu đủ, xoài. Đặt cây Tết hài hòa với bàn thờ, mâm ngũ quả — không để cây quá to che bàn thờ — giúp không gian ngày Tết trang trọng và ấm cúng."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Chưng mai và đào cùng lúc có được không?"},{"type":"p","text":"Được. Nhiều gia đình chưng cả hai. Quan trọng là bày cân đối, đủ chỗ thoáng cho mỗi cây."},{"type":"h3","text":"Cây Tết đặt ở đâu trong nhà là tốt?"},{"type":"p","text":"Theo thói quen dân gian, cây hoa lớn thường đặt phòng khách hoặc trước cửa để đón khách. Về thực tế, nên đặt chỗ có ánh sáng tốt để hoa bền."},{"type":"h3","text":"Tắc kiểng rụng trái nhiều là sao?"},{"type":"p","text":"Thường do thiếu nước, đổi chỗ đột ngột hoặc vận chuyển va đập. Tưới đều, đặt chỗ sáng thoáng, hạn chế dời chậu."},{"type":"products","title":"Dùng trong bài này","slugs":["tac-cam-thach-thai","mai-dia-thao","tung-thom"]},{"type":"p","text":"Xem thêm [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet) và [những điều kiêng kỵ khi đặt cây trong nhà](/goc-cham-cay/kieng-ky-khi-dat-cay-trong-nha)."}]$j$, 4, ARRAY[]::text[], ARRAY[$j$cây Tết$j$,$j$phong thủy$j$,$j$mai vàng$j$]::text[], $j$Ý nghĩa các loại cây chưng Tết theo quan niệm dân gian: mai vàng, đào, quất, cúc, vạn thọ, tùng; cách chọn và bày cây Tết hợp nhà phố, căn hộ.$j$, $j$2026-11-30 07:30:00+07$j$),
($j$trang-tri-cay-xanh-tet-can-ho-nho$j$, $j$decor$j$, $j$🏡 Trang trí cây xanh ngày Tết cho căn hộ nhỏ: ít chậu mà vẫn rộn ràng, gọn gàng$j$, $j$Căn hộ nhỏ chỉ cần 3–5 điểm xanh đúng chỗ là có không khí Tết: một chậu hoa chính ở phòng khách, cây nhỏ trên bàn trà, chậu cúc hoặc tắc ngoài ban công. Chọn chậu gọn, màu đỏ vàng, thêm vài phụ kiện Tết và giữ lối đi thông thoáng.$j$, $j$[{"type":"p","text":"Căn hộ chung cư hay nhà phố nhỏ khó đặt chậu mai lớn như nhà vườn. Nhưng không khí Tết không phụ thuộc vào số lượng chậu: **vài điểm xanh, đỏ, vàng đặt đúng chỗ** là đủ làm căn nhà rộn ràng."},{"type":"h2","text":"🎯 Công thức 3 – 5 điểm xanh"},{"type":"table","rows":[["Điểm","Vị trí","Gợi ý"],["Điểm chính","Góc phòng khách","1 chậu mai nhỏ, cành mai cắm bình hoặc chậu hoa lớn"],["Điểm phụ","Bàn trà, kệ tivi","Chậu cúc nhỏ, lan, cây kiểng lá màu đỏ (phú quý)"],["Lối vào","Kệ giày, cạnh cửa","Chậu nhỏ gọn, không vướng lối đi"],["Ban công","Lan can, góc ban công","Cặp tắc nhỏ, cúc, vạn thọ — cây cần nắng"],["Bàn ăn","Giữa bàn","Bình hoa thấp hoặc chậu cây nhỏ sạch đất"]]},{"type":"h2","text":"🎨 Chọn màu và chậu"},{"type":"list","items":["Tông chủ đạo đỏ – vàng – xanh: hoa vàng, lá xanh, chậu hoặc phụ kiện đỏ.","Chậu cùng một tông (gốm trắng, đất nung, mây tre) giúp nhà nhỏ trông gọn, không rối mắt.","Bọc chậu nhựa bằng giỏ mây, vải đỏ thay vì mua chậu mới đắt tiền.","Treo thêm vài bao lì xì, câu đối nhỏ lên cây xanh có sẵn (trầu bà, lưỡi hổ) cũng thành cây Tết."],"ordered":false},{"type":"h2","text":"🌿 Dùng cây xanh sẵn có"},{"type":"p","text":"Không nhất thiết phải mua cây mới. Trầu bà đế vương, phú quý, ngọc ngân, lưỡi hổ trong nhà chỉ cần lau sạch lá, thay lớp sỏi mặt chậu, thêm nơ đỏ và vài phụ kiện là hòa vào không khí Tết. Cây lá màu đỏ như phú quý rất hợp những ngày đầu năm."},{"type":"h2","text":"☀️ Giữ hoa bền trong căn hộ"},{"type":"list","items":["Căn hộ thường thiếu nắng và có máy lạnh: hoa chưng trong nhà vài ngày rồi luân phiên ra ban công.","Không đặt chậu hoa trước cửa gió máy lạnh, cạnh bếp.","Tưới gốc mỗi sáng, không tưới lên hoa.","Ngắt hoa tàn hằng ngày."],"ordered":false},{"type":"p","text":"Xem chi tiết: [chăm cúc chưng Tết bền hoa](/goc-cham-cay/cham-cuc-chung-tet-ben-hoa) và [ý nghĩa các cây chưng Tết](/goc-cham-cay/chung-cay-gi-ngay-tet-y-nghia)."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt quá nhiều chậu** làm lối đi chật, khó dọn dẹp ngày Tết.","**Chậu to, nặng** trên ban công nhỏ, khó di chuyển.","**Phụ kiện che kín lá**: cây bí, mau úa.","**Dùng đèn nháy nóng quấn sát lá**: lá cháy, nguy cơ chập điện khi tưới."],"ordered":false},{"type":"h2","text":"🛒 Danh sách mua sắm gợi ý"},{"type":"table","rows":[["Món","Số lượng","Ghi chú"],["Chậu hoa chính (mai nhỏ, lan, cúc)","1","Cỡ vừa, hợp góc phòng khách"],["Chậu cây nhỏ để bàn","1–2","Phú quý, ngọc ngân"],["Cây ban công","1–2","Tắc nhỏ, cúc, vạn thọ"],["Phụ kiện","Vài món","Nơ đỏ, bao lì xì, dây đèn LED ít tỏa nhiệt"],["Sỏi phủ mặt chậu","1 túi","Cho chậu sạch đẹp"]]},{"type":"h2","text":"🔌 An toàn khi trang trí đèn"},{"type":"p","text":"Dây đèn trang trí cho cây nên chọn loại LED ít tỏa nhiệt, có nguồn rõ ràng. Không quấn dây quá chặt vào cành, không để ổ cắm, phích cắm dưới chậu hoặc chỗ dễ đọng nước tưới. Tắt đèn khi ra khỏi nhà và khi đi ngủ. Ban công ngoài trời nên dùng loại đèn chịu được ẩm."},{"type":"h2","text":"🧹 Chuẩn bị trước ngày cây về"},{"type":"list","items":["Dọn trống và lau sạch chỗ định đặt cây.","Chuẩn bị đĩa lót, khay hứng nước cho từng chậu.","Xem trước hướng nắng của ban công để đặt cây hoa đúng chỗ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Căn hộ không có ban công thì chưng hoa gì?"},{"type":"p","text":"Chọn hoa bền trong điều kiện ít nắng như lan, hoặc cắm cành mai, cành đào trong bình. Kết hợp cây kiểng lá chịu bóng trang trí phụ kiện Tết."},{"type":"h3","text":"Chung cư có cho để chậu ngoài hành lang?"},{"type":"p","text":"Nhiều tòa nhà không cho để vật dụng ở hành lang vì lối thoát hiểm. Nên hỏi ban quản lý trước."},{"type":"h3","text":"Sau Tết làm gì với cây?"},{"type":"p","text":"Gỡ phụ kiện, đưa cây về chỗ cũ, cây hoa thì chăm phục hồi. Xem [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."},{"type":"products","title":"Dùng trong bài này","slugs":["phu-quy","trau-ba-de-vuong-do","mai-dia-thao","tac-cam-thach-thai"]},{"type":"p","text":"Xem thêm [trang trí ban công chung cư nhỏ](/goc-cham-cay/trang-tri-ban-cong-chung-cu-nho)."}]$j$, 4, ARRAY[]::text[], ARRAY[$j$decor Tết$j$,$j$chung cư$j$,$j$cây Tết$j$]::text[], $j$Gợi ý trang trí cây xanh ngày Tết cho căn hộ nhỏ, chung cư: chọn cây chính, cây phụ, chậu, phụ kiện Tết, vị trí đặt và cách giữ hoa bền.$j$, $j$2026-12-01 07:30:00+07$j$)) AS v(slug, cat, title, excerpt, body, minutes, diseases, tags, seo, pub)
WHERE NOT EXISTS (SELECT 1 FROM "posts" x WHERE x."slug" = v.slug);
